
-- Full Circle Instructor Insights and first-finder Scripture discoveries.
-- Original editorial guidance: archaeology / history, theological reading,
-- and present-day application must not be conflated or presented as proof.
-- The quiz answer bank remains private. All prize claims serialize on a
-- single question row and are settled with a database transaction.

create table if not exists public.instructor_verse_contexts (
 reference text primary key,historical_context text not null,spiritual_context text not null,
 present_day_context text not null,
 research_note text not null default 'Original editorial passage guide',
 source_links jsonb not null default '[]'::jsonb,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
alter table public.instructor_verse_contexts enable row level security;
drop policy if exists "Read published instructor verse context" on public.instructor_verse_contexts;
create policy "Read published instructor verse context" on public.instructor_verse_contexts for select to anon,authenticated using (true);
revoke all on public.instructor_verse_contexts from public,anon,authenticated;
grant select on public.instructor_verse_contexts to anon,authenticated;

create table if not exists public.verse_quest_templates (
 id bigint generated always as identity primary key,reference text not null unique,
 question text not null, choices jsonb not null, correct_answer text not null,
 explanation text not null,enabled boolean not null default true
);
alter table public.verse_quest_templates enable row level security;
revoke all on public.verse_quest_templates from public,anon,authenticated;

create table if not exists public.quarterly_verse_quests (
 id uuid primary key default gen_random_uuid(),quarter_start date not null,
 reference text not null,question text not null,choices jsonb not null,
 correct_answer text not null,explanation text not null,
 prize_type text not null check (prize_type in ('fcx_ticket','relic','denarii')),
 prize_quantity integer not null default 1 check(prize_quantity>0),
 relic_slug text,winner_user_id uuid references public.profiles(id),claimed_at timestamptz,
 created_at timestamptz not null default now(),unique(quarter_start,reference),
 constraint won_timestamp_consistency check ((winner_user_id is null and claimed_at is null)
 or (winner_user_id is not null and claimed_at is not null))
);
create index if not exists quarterly_verse_quests_quarter_lookup
 on public.quarterly_verse_quests(quarter_start,reference) where winner_user_id is null;
alter table public.quarterly_verse_quests enable row level security;
revoke all on public.quarterly_verse_quests from public,anon,authenticated;

create table if not exists public.quarterly_verse_quest_attempts (
 quest_id uuid not null references public.quarterly_verse_quests(id),
 user_id uuid not null references public.profiles(id),submitted_answer text not null,
 is_correct boolean not null,created_at timestamptz not null default now(),
 primary key(quest_id,user_id)
);
alter table public.quarterly_verse_quest_attempts enable row level security;
revoke all on public.quarterly_verse_quest_attempts from public,anon,authenticated;

create table if not exists public.quarterly_verse_fcx_awards (
 quest_id uuid primary key references public.quarterly_verse_quests(id),
 user_id uuid not null references public.profiles(id),
 event_id uuid references public.fcx_events(id),
 status text not null check(status in ('registered','awaiting_event')),
 created_at timestamptz not null default now()
);
alter table public.quarterly_verse_fcx_awards enable row level security;
revoke all on public.quarterly_verse_fcx_awards from public,anon,authenticated;

-- Expand passage-level research summaries into verse-specific lookup rows.
insert into public.instructor_verse_contexts(reference,historical_context,spiritual_context,present_day_context,research_note,source_links)
select verse.value,grp.historical_context,grp.spiritual_context,grp.present_day_context,
 grp.research_note,grp.source_links
from jsonb_to_recordset('[{"historical_context":"Acts describes Pentecost within Jerusalem''s pilgrimage festival setting, followed by public preaching and new patterns of common life. The account tells a theological story of an expanding movement.","spiritual_context":"The Spirit''s coming leads to witness, learning, generosity and shared responsibility. The community''s public credibility is tied to how it treats people.","present_day_context":"Let spiritual enthusiasm mature into habits: teaching, transparent stewardship, hospitality and mutual care. A movement grows strong when it can sustain its commitments.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash","https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"],"refs":["Acts 2:1","Acts 2:10","Acts 2:11","Acts 2:12","Acts 2:13","Acts 2:14","Acts 2:15","Acts 2:16","Acts 2:17","Acts 2:18","Acts 2:19","Acts 2:2","Acts 2:20","Acts 2:21","Acts 2:22","Acts 2:23","Acts 2:24","Acts 2:25","Acts 2:26","Acts 2:27","Acts 2:28","Acts 2:29","Acts 2:3","Acts 2:30","Acts 2:31","Acts 2:32","Acts 2:33","Acts 2:34","Acts 2:35","Acts 2:36","Acts 2:37","Acts 2:38","Acts 2:39","Acts 2:4","Acts 2:40","Acts 2:41","Acts 2:42","Acts 2:43","Acts 2:44","Acts 2:45","Acts 2:46","Acts 2:47","Acts 2:5","Acts 2:6","Acts 2:7","Acts 2:8","Acts 2:9"]},{"historical_context":"After the initial rout, other Israelites join the pursuit and control river crossings. The story moves from a small opening team to wider coordinated participation.","spiritual_context":"A breakthrough can begin with a few and still need many hands to sustain it. Faithfulness includes inviting others into the work instead of guarding credit.","present_day_context":"When an initiative gains momentum, establish responsible handoffs and involve capable partners. Expansion is a stewardship task, not a personal trophy.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.asor.org/news/2019/03/nea82_1-toc/","https://www.sefaria.org/topics/midrash"],"refs":["Judges 7:23","Judges 7:24","Judges 7:25"]},{"historical_context":"Daniel 3 portrays an imperial image and a public demand for conformity. The narrative dramatizes religious allegiance under political coercion.","spiritual_context":"The three companions refuse to make obedience conditional on a guaranteed rescue. Their courage remains meaningful even without control over the outcome.","present_day_context":"Decide which ethical boundaries cannot be negotiated for career comfort. Prepare to bear consequences without demeaning those who disagree.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"],"refs":["Daniel 3:1","Daniel 3:10","Daniel 3:11","Daniel 3:12","Daniel 3:13","Daniel 3:14","Daniel 3:15","Daniel 3:16","Daniel 3:17","Daniel 3:18","Daniel 3:19","Daniel 3:2","Daniel 3:20","Daniel 3:21","Daniel 3:22","Daniel 3:23","Daniel 3:24","Daniel 3:25","Daniel 3:26","Daniel 3:27","Daniel 3:28","Daniel 3:29","Daniel 3:3","Daniel 3:30","Daniel 3:4","Daniel 3:5","Daniel 3:6","Daniel 3:7","Daniel 3:8","Daniel 3:9"]},{"historical_context":"Deuteronomy addresses Israel as a covenant community, teaching households to remember, repeat and embody the law. The Shema became central in later Jewish prayer and instruction.","spiritual_context":"Love of God is tied to ordinary rhythms: conversation, memory, family and practice. Kingdom values survive when they become shared habits rather than occasional speeches.","present_day_context":"Translate one conviction into a daily habit that others can observe and learn. Culture is changed more reliably by repeated example than by a single inspiring event.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Deuteronomy 6:1","Deuteronomy 6:10","Deuteronomy 6:11","Deuteronomy 6:12","Deuteronomy 6:13","Deuteronomy 6:14","Deuteronomy 6:15","Deuteronomy 6:16","Deuteronomy 6:17","Deuteronomy 6:18","Deuteronomy 6:19","Deuteronomy 6:2","Deuteronomy 6:20","Deuteronomy 6:21","Deuteronomy 6:22","Deuteronomy 6:23","Deuteronomy 6:24","Deuteronomy 6:25","Deuteronomy 6:3","Deuteronomy 6:4","Deuteronomy 6:5","Deuteronomy 6:6","Deuteronomy 6:7","Deuteronomy 6:8","Deuteronomy 6:9"]},{"historical_context":"Ezekiel addresses a community shaped by exile in Babylonia. The valley of dry bones is a prophetic vision about Israel''s restoration, not an archaeological report of a particular valley.","spiritual_context":"The vision gives language to a people who think their future is over. Hope is more than optimism: it imagines renewal beyond visible capacity.","present_day_context":"When a team has lost hope, name the damage honestly and rebuild conditions for life: trust, resources, shared purpose and consistent action.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"],"refs":["Ezekiel 37:1","Ezekiel 37:10","Ezekiel 37:11","Ezekiel 37:12","Ezekiel 37:13","Ezekiel 37:14","Ezekiel 37:2","Ezekiel 37:3","Ezekiel 37:4","Ezekiel 37:5","Ezekiel 37:6","Ezekiel 37:7","Ezekiel 37:8","Ezekiel 37:9"]},{"historical_context":"Genesis opens with a patterned creation account, naming God as creator and ordering domains of light, land, life and humanity. Ancient Near Eastern creation traditions provide a comparison; their existence does not settle how every detail should be read.","spiritual_context":"The repeated divine evaluation of goodness frames creation as purposeful rather than disposable. In Christian interpretation, people image God''s rule through responsible stewardship, not control over other people.","present_day_context":"Look at something neglected around you and imagine what order, care and creativity could make possible. Begin with one faithful act of stewardship rather than waiting for a title.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://answersingenesis.org/archaeology/fact-checking-bible/","https://www.sefaria.org/topics/midrash"],"refs":["Genesis 1:1","Genesis 1:10","Genesis 1:11","Genesis 1:12","Genesis 1:13","Genesis 1:14","Genesis 1:15","Genesis 1:16","Genesis 1:17","Genesis 1:18","Genesis 1:19","Genesis 1:2","Genesis 1:20","Genesis 1:21","Genesis 1:22","Genesis 1:23","Genesis 1:24","Genesis 1:25","Genesis 1:26","Genesis 1:27","Genesis 1:28","Genesis 1:29","Genesis 1:3","Genesis 1:30","Genesis 1:31","Genesis 1:4","Genesis 1:5","Genesis 1:6","Genesis 1:7","Genesis 1:8","Genesis 1:9"]},{"historical_context":"Gideon approaches the enemy camp at night and overhears a dream interpreted as a sign of defeat. The account uses a story-within-the-story to build confidence at a fragile moment.","spiritual_context":"Reassurance comes alongside a concrete next step. Gideon''s worship precedes action; reflection and initiative belong together.","present_day_context":"When anxiety is high, seek credible perspective before making decisions. Let encouragement lead to responsible movement rather than endless preparation.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.thetorah.com/article/questioning-gods-call-moses-versus-gideon","https://www.sefaria.org/topics/midrash"],"refs":["Judges 7:10","Judges 7:11","Judges 7:12","Judges 7:13","Judges 7:14","Judges 7:15","Judges 7:9"]},{"historical_context":"Gideon is introduced threshing wheat in a winepress during a period of insecurity. The call scene resembles other biblical commissioning narratives, including Moses'' objections and divine reassurance.","spiritual_context":"The messenger calls Gideon capable before Gideon sees evidence of that capacity. The text pairs calling with questioning rather than pretending fear is absent.","present_day_context":"Do not wait for confidence to arrive before developing competence. Name the task, acknowledge your limitations and take a testable first step.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.thetorah.com/article/questioning-gods-call-moses-versus-gideon","https://www.sefaria.org/topics/midrash"],"refs":["Judges 6:11","Judges 6:12","Judges 6:13","Judges 6:14","Judges 6:15","Judges 6:16","Judges 6:17","Judges 6:18","Judges 6:19","Judges 6:20","Judges 6:21","Judges 6:22","Judges 6:23","Judges 6:24"]},{"historical_context":"Gideon''s army gathers near the spring of Harod as the Midianites camp opposite. The story emphasizes a drastic reduction of fighting men; its details are the narrator''s theological account, not a modern military handbook.","spiritual_context":"The small force removes an easy claim of self-sufficiency. The spiritual theme is dependence coupled with deliberate preparation, not celebrating lack of planning.","present_day_context":"Being under-resourced does not automatically make a project holy, but a small committed team can accomplish focused work. Define the mission and remove unnecessary complexity.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.thetorah.com/article/questioning-gods-call-moses-versus-gideon","https://www.asor.org/news/2019/03/nea82_1-toc/"],"refs":["Judges 7:1","Judges 7:2","Judges 7:3","Judges 7:4","Judges 7:5","Judges 7:6","Judges 7:7","Judges 7:8"]},{"historical_context":"Gideon''s first assignment confronts an altar in his own household, and the ensuing dispute shows how deeply public worship and family loyalties can intersect.","spiritual_context":"The narrative places internal reform before public victory. The fleece scene also portrays an anxious leader seeking reassurance, not a universal formula for testing God.","present_day_context":"Challenge harmful customs with preparation, accountability and respect for the people affected. Lasting reform begins close to home and should not depend on spectacle.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.thetorah.com/article/questioning-gods-call-moses-versus-gideon","https://www.sefaria.org/topics/midrash"],"refs":["Judges 6:25","Judges 6:26","Judges 6:27","Judges 6:28","Judges 6:29","Judges 6:30","Judges 6:31","Judges 6:32","Judges 6:33","Judges 6:34","Judges 6:35","Judges 6:36","Judges 6:37","Judges 6:38","Judges 6:39","Judges 6:40"]},{"historical_context":"Habakkuk imagines a prophet on watch, waiting for a response to injustice and uncertainty. The written vision is meant to be readable and carried forward.","spiritual_context":"Waiting and faithfulness are active, not passive. The text invites perseverance when arrogant power seems to prosper.","present_day_context":"Write the problem and the desired change clearly enough that others can act. Pair patience with preparation and resist shortcuts that betray your values.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Habakkuk 2:1","Habakkuk 2:2","Habakkuk 2:3","Habakkuk 2:4"]},{"historical_context":"In a divided urban church at Corinth, Paul explains spiritual gifts through the image of one body with many members. The social setting included differences in status and contribution.","spiritual_context":"No one gift authorizes contempt for another part of the body. Spiritual maturity honors interdependence and dignifies less visible people.","present_day_context":"Build teams where quieter skills matter and resources are shared. A healthy organization gives dignity to members who do not attract applause.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en","https://www.sefaria.org/topics/midrash"],"refs":["1 Corinthians 12:1","1 Corinthians 12:10","1 Corinthians 12:11","1 Corinthians 12:12","1 Corinthians 12:13","1 Corinthians 12:14","1 Corinthians 12:15","1 Corinthians 12:16","1 Corinthians 12:17","1 Corinthians 12:18","1 Corinthians 12:19","1 Corinthians 12:2","1 Corinthians 12:20","1 Corinthians 12:21","1 Corinthians 12:22","1 Corinthians 12:23","1 Corinthians 12:24","1 Corinthians 12:25","1 Corinthians 12:26","1 Corinthians 12:27","1 Corinthians 12:28","1 Corinthians 12:29","1 Corinthians 12:3","1 Corinthians 12:30","1 Corinthians 12:31","1 Corinthians 12:4","1 Corinthians 12:5","1 Corinthians 12:6","1 Corinthians 12:7","1 Corinthians 12:8","1 Corinthians 12:9"]},{"historical_context":"In the closing Joseph story, the brothers fear retaliation after their father''s death. The social stakes are concrete: powerful officials could use their position to settle family scores.","spiritual_context":"Joseph refuses to make revenge the final interpretation of the harm done to him. His response does not make evil good; it chooses a different future from the one his brothers imagined.","present_day_context":"What painful experience can you transform into a commitment to protect, build or serve others? Forgiveness need not remove boundaries, but it can free leadership from retaliation.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://adfonteslibrary.org/work-st-josephus-antiquities-1"],"refs":["Genesis 50:15","Genesis 50:16","Genesis 50:17","Genesis 50:18","Genesis 50:19","Genesis 50:20","Genesis 50:21"]},{"historical_context":"Isaiah 58 addresses religious fasting and social conduct together, highlighting exploitation, hunger and neglect. Prophetic rhetoric assesses worship through its effects on human relationships.","spiritual_context":"The passage refuses to separate devotion from justice. Repair, generosity and changed treatment of workers become visible signs of faithful worship.","present_day_context":"If religious activity coexists with unfair treatment, improve the treatment. Start with wages, access, hospitality and systems that protect vulnerable people.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Isaiah 58:1","Isaiah 58:10","Isaiah 58:11","Isaiah 58:12","Isaiah 58:13","Isaiah 58:14","Isaiah 58:2","Isaiah 58:3","Isaiah 58:4","Isaiah 58:5","Isaiah 58:6","Isaiah 58:7","Isaiah 58:8","Isaiah 58:9"]},{"historical_context":"Isaiah''s throne vision appears within the context of Judah''s monarchy and public anxiety after the death of King Uzziah. Prophetic calling literature uses imagery as well as speech.","spiritual_context":"Isaiah''s willingness to be sent follows a moment of humility and cleansing. Courage is not self-importance; it begins with accountable transformation.","present_day_context":"Before attempting to reform a community, examine your own motives. Let conviction move you toward service even when the assignment is difficult.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Isaiah 6:1","Isaiah 6:10","Isaiah 6:11","Isaiah 6:12","Isaiah 6:13","Isaiah 6:2","Isaiah 6:3","Isaiah 6:4","Isaiah 6:5","Isaiah 6:6","Isaiah 6:7","Isaiah 6:8","Isaiah 6:9"]},{"historical_context":"James challenges favoritism toward the wealthy in an assembly and asks what genuine faith does for neighbors lacking necessities. The argument is intensely practical.","spiritual_context":"Faith is treated as living trust expressed through deeds, not merely verbal assurance. Partiality reveals a failure to see equal human dignity.","present_day_context":"Examine whose voice gets attention in your meetings and who goes without basic support. Put convictions into budgets, decisions and measurable care.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["James 2:1","James 2:10","James 2:11","James 2:12","James 2:13","James 2:14","James 2:15","James 2:16","James 2:17","James 2:18","James 2:19","James 2:2","James 2:20","James 2:21","James 2:22","James 2:23","James 2:24","James 2:25","James 2:26","James 2:3","James 2:4","James 2:5","James 2:6","James 2:7","James 2:8","James 2:9"]},{"historical_context":"Jeremiah is called amid the final era of Judah''s monarchy, when international pressure and internal conflict are rising. Prophetic texts combine history, poetry and symbolic action.","spiritual_context":"The call refuses to make youth or insecurity the decisive qualification. The emphasis falls on faithfulness to the message and perseverance under resistance.","present_day_context":"Learn from experienced people without surrendering responsible initiative. Take early opportunities to speak truth carefully and do the work assigned to you.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Jeremiah 1:1","Jeremiah 1:10","Jeremiah 1:11","Jeremiah 1:12","Jeremiah 1:13","Jeremiah 1:14","Jeremiah 1:15","Jeremiah 1:16","Jeremiah 1:17","Jeremiah 1:18","Jeremiah 1:19","Jeremiah 1:2","Jeremiah 1:3","Jeremiah 1:4","Jeremiah 1:5","Jeremiah 1:6","Jeremiah 1:7","Jeremiah 1:8","Jeremiah 1:9"]},{"historical_context":"Joseph''s account unfolds within a large pastoral family where inheritance, status and rivalry matter. The garment and dreams sharpen a household conflict that eventually leads to forced movement into Egypt.","spiritual_context":"The passage shows giftedness existing alongside immature relationships and serious injustice. A calling is not permission to ignore the consequences of how people are treated.","present_day_context":"When envy or favoritism damages a team, avoid responding with the same tactics. Build character, skill and reconciliation even when circumstances are unfair.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://adfonteslibrary.org/work-st-josephus-antiquities-1"],"refs":["Genesis 37:1","Genesis 37:10","Genesis 37:11","Genesis 37:12","Genesis 37:13","Genesis 37:14","Genesis 37:15","Genesis 37:16","Genesis 37:17","Genesis 37:18","Genesis 37:19","Genesis 37:2","Genesis 37:20","Genesis 37:21","Genesis 37:22","Genesis 37:23","Genesis 37:24","Genesis 37:25","Genesis 37:26","Genesis 37:27","Genesis 37:28","Genesis 37:29","Genesis 37:3","Genesis 37:30","Genesis 37:31","Genesis 37:32","Genesis 37:33","Genesis 37:34","Genesis 37:35","Genesis 37:36","Genesis 37:4","Genesis 37:5","Genesis 37:6","Genesis 37:7","Genesis 37:8","Genesis 37:9"]},{"historical_context":"Joshua''s commission follows Moses'' death as Israel faces a leadership transition. The narrative combines territory, covenant law, communal loyalty and a new command structure.","spiritual_context":"Courage is paired with meditation on the law and faithful action. Biblical boldness is not independence from accountability; Joshua is told how to stay oriented.","present_day_context":"When responsibility moves to you, secure shared values before pursuing visible wins. Make a plan, invite cooperation and take the next necessary step.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://answersingenesis.org/archaeology/fact-checking-bible/","https://www.sefaria.org/topics/midrash"],"refs":["Joshua 1:1","Joshua 1:10","Joshua 1:11","Joshua 1:12","Joshua 1:13","Joshua 1:14","Joshua 1:15","Joshua 1:16","Joshua 1:17","Joshua 1:18","Joshua 1:2","Joshua 1:3","Joshua 1:4","Joshua 1:5","Joshua 1:6","Joshua 1:7","Joshua 1:8","Joshua 1:9"]},{"historical_context":"Judges 3 introduces testing, local conflict and the stories of Othniel, Ehud and Shamgar. The narratives reflect varied communities and unusual deliverers rather than one uniform model of leadership.","spiritual_context":"The deliverers illustrate that rescue can arrive through people who do not fit expected molds. Violence in these ancient accounts calls for careful interpretation rather than uncritical imitation.","present_day_context":"Do not dismiss someone because their background or strengths are unconventional. Find constructive solutions that challenge stale assumptions without harming others.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.asor.org/news/2019/03/nea82_1-toc/","https://www.sefaria.org/topics/midrash"],"refs":["Judges 3:1","Judges 3:10","Judges 3:11","Judges 3:12","Judges 3:13","Judges 3:14","Judges 3:15","Judges 3:16","Judges 3:17","Judges 3:18","Judges 3:19","Judges 3:2","Judges 3:20","Judges 3:21","Judges 3:22","Judges 3:23","Judges 3:24","Judges 3:25","Judges 3:26","Judges 3:27","Judges 3:28","Judges 3:29","Judges 3:3","Judges 3:30","Judges 3:31","Judges 3:4","Judges 3:5","Judges 3:6","Judges 3:7","Judges 3:8","Judges 3:9"]},{"historical_context":"Judges 4 presents Deborah as prophet and judge, Barak as military leader, and Jael as an unexpected actor. Hazor and the northern region belong to a richly studied archaeological landscape; direct verification of each scene is a separate question.","spiritual_context":"The story distributes initiative across several people rather than a single heroic figure. Courage and responsibility can come from voices a culture underestimates.","present_day_context":"Ask whose capacity is being overlooked in your group. Give responsibility to proven character and insight rather than only to familiar titles.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.asor.org/news/2019/03/nea82_1-toc/","https://www.sefaria.org/topics/midrash"],"refs":["Judges 4:1","Judges 4:10","Judges 4:11","Judges 4:12","Judges 4:13","Judges 4:14","Judges 4:15","Judges 4:16","Judges 4:17","Judges 4:18","Judges 4:19","Judges 4:2","Judges 4:20","Judges 4:21","Judges 4:22","Judges 4:23","Judges 4:24","Judges 4:3","Judges 4:4","Judges 4:5","Judges 4:6","Judges 4:7","Judges 4:8","Judges 4:9"]},{"historical_context":"Judges 5 is ancient victory poetry, using song, geography and tribal names to remember a conflict. Poetry compresses and interprets events differently from Judges 4''s narrative prose.","spiritual_context":"The song praises willing participation and exposes the cost of indifference. Shared courage is treated as a communal choice, not merely a leader''s personality.","present_day_context":"Celebrate the people who carry difficult work, not only the people standing at the front. Build teams in which contribution is visible and apathy can be challenged.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.asor.org/news/2019/03/nea82_1-toc/","https://www.sefaria.org/topics/midrash"],"refs":["Judges 5:1","Judges 5:10","Judges 5:11","Judges 5:12","Judges 5:13","Judges 5:14","Judges 5:15","Judges 5:16","Judges 5:17","Judges 5:18","Judges 5:19","Judges 5:2","Judges 5:20","Judges 5:21","Judges 5:22","Judges 5:23","Judges 5:24","Judges 5:25","Judges 5:26","Judges 5:27","Judges 5:28","Judges 5:29","Judges 5:3","Judges 5:30","Judges 5:31","Judges 5:4","Judges 5:5","Judges 5:6","Judges 5:7","Judges 5:8","Judges 5:9"]},{"historical_context":"Judges 8 records conflict after victory, Gideon''s response to rivals and the family''s later legacy. The narrative includes consequences that complicate a simplistic heroic reading.","spiritual_context":"Winning a battle does not guarantee healthy leadership afterward. The account presses readers to evaluate ambition, memory and loyalty after public success.","present_day_context":"Plan for the season after a major win. Protect relationships, finances and succession instead of letting applause excuse unwise choices.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Judges 8:1","Judges 8:10","Judges 8:11","Judges 8:12","Judges 8:13","Judges 8:14","Judges 8:15","Judges 8:16","Judges 8:17","Judges 8:18","Judges 8:19","Judges 8:2","Judges 8:20","Judges 8:21","Judges 8:22","Judges 8:23","Judges 8:24","Judges 8:25","Judges 8:26","Judges 8:27","Judges 8:28","Judges 8:29","Judges 8:3","Judges 8:30","Judges 8:31","Judges 8:32","Judges 8:33","Judges 8:34","Judges 8:35","Judges 8:4","Judges 8:5","Judges 8:6","Judges 8:7","Judges 8:8","Judges 8:9"]},{"historical_context":"Judges begins with incomplete settlement and local struggles following Joshua. Its account of tribal alliances and contested cities belongs to the Bible''s portrait of early Israel; archaeological models of settlement differ.","spiritual_context":"The opening chapter resists a simplistic triumphal narrative: progress and compromise occur together. Shared responsibility can be weakened when groups pursue only local interests.","present_day_context":"A fragmented organization may have many victories and still lack a common direction. Build coalitions and confront unfinished work without blaming the next generation.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.asor.org/news/2019/03/nea82_1-toc/","https://www.sefaria.org/topics/midrash"],"refs":["Judges 1:1","Judges 1:10","Judges 1:11","Judges 1:12","Judges 1:13","Judges 1:14","Judges 1:15","Judges 1:16","Judges 1:17","Judges 1:18","Judges 1:19","Judges 1:2","Judges 1:20","Judges 1:21","Judges 1:22","Judges 1:23","Judges 1:24","Judges 1:25","Judges 1:26","Judges 1:27","Judges 1:28","Judges 1:29","Judges 1:3","Judges 1:30","Judges 1:31","Judges 1:32","Judges 1:33","Judges 1:34","Judges 1:35","Judges 1:36","Judges 1:4","Judges 1:5","Judges 1:6","Judges 1:7","Judges 1:8","Judges 1:9"]},{"historical_context":"Luke locates Jesus'' public reading within synagogue practice and Isaiah''s language of release and good news. The narrative frames his mission using Israel''s prophetic tradition.","spiritual_context":"Anointing is connected with service to the poor, captives and oppressed, not merely private prestige. Spiritual power has a concrete human direction.","present_day_context":"Describe your mission in terms of who benefits. Choose a tangible act that brings dignity, inclusion or relief rather than a slogan about impact.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Luke 4:16","Luke 4:17","Luke 4:18","Luke 4:19","Luke 4:20","Luke 4:21"]},{"historical_context":"Matthew presents Jesus teaching disciples and crowds in the Sermon on the Mount, a sustained reorientation of righteousness, mercy and community life within first-century Judaism.","spiritual_context":"The teaching moves beyond reputation toward transformed intention and conduct. Light, peacemaking and integrity describe a community whose witness is practical.","present_day_context":"What would your workplace or neighborhood notice if these values shaped speech, conflict, generosity and truthfulness? Change one everyday interaction first.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Matthew 5:1","Matthew 5:10","Matthew 5:11","Matthew 5:12","Matthew 5:13","Matthew 5:14","Matthew 5:15","Matthew 5:16","Matthew 5:17","Matthew 5:18","Matthew 5:19","Matthew 5:2","Matthew 5:20","Matthew 5:21","Matthew 5:22","Matthew 5:23","Matthew 5:24","Matthew 5:25","Matthew 5:26","Matthew 5:27","Matthew 5:28","Matthew 5:29","Matthew 5:3","Matthew 5:30","Matthew 5:31","Matthew 5:32","Matthew 5:33","Matthew 5:34","Matthew 5:35","Matthew 5:36","Matthew 5:37","Matthew 5:38","Matthew 5:39","Matthew 5:4","Matthew 5:40","Matthew 5:41","Matthew 5:42","Matthew 5:43","Matthew 5:44","Matthew 5:45","Matthew 5:46","Matthew 5:47","Matthew 5:48","Matthew 5:5","Matthew 5:6","Matthew 5:7","Matthew 5:8","Matthew 5:9"]},{"historical_context":"Micah uses covenant-lawsuit language to question hollow offerings and unjust behavior in Judah. The familiar summary of justice, mercy and humility appears in this larger prophetic dispute.","spiritual_context":"The passage places everyday ethics at the center of covenant faithfulness. Dramatic gestures cannot compensate for cruelty or dishonesty.","present_day_context":"Choose one measurable repair: fairness in a decision, mercy toward a vulnerable person, or humility in admitting error. Let reform become visible.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Micah 6:1","Micah 6:2","Micah 6:3","Micah 6:4","Micah 6:5","Micah 6:6","Micah 6:7","Micah 6:8"]},{"historical_context":"Naaman''s journey crosses the kingdoms of Aram and Israel and involves soldiers, servants, a prophet and Jordan River washing. Social rank and international tensions make the humble instruction striking.","spiritual_context":"The healing narrative centers trust and obedience in an unexpectedly simple direction. Servants help a powerful person accept correction.","present_day_context":"Good advice often arrives from people without high status. Build a culture where leaders can be corrected and simple effective solutions are not dismissed.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["2 Kings 5:1","2 Kings 5:10","2 Kings 5:11","2 Kings 5:12","2 Kings 5:13","2 Kings 5:14","2 Kings 5:15","2 Kings 5:16","2 Kings 5:17","2 Kings 5:18","2 Kings 5:19","2 Kings 5:2","2 Kings 5:20","2 Kings 5:21","2 Kings 5:22","2 Kings 5:23","2 Kings 5:24","2 Kings 5:25","2 Kings 5:26","2 Kings 5:27","2 Kings 5:3","2 Kings 5:4","2 Kings 5:5","2 Kings 5:6","2 Kings 5:7","2 Kings 5:8","2 Kings 5:9"]},{"historical_context":"Nehemiah serves in a Persian imperial court before requesting permission and resources to rebuild Jerusalem''s walls. Persian-period Judea is attested through material and written evidence, though details require case-by-case evaluation.","spiritual_context":"Nehemiah prays, asks, surveys and organizes. Spiritual burden and practical planning are presented as partners, not competitors.","present_day_context":"Translate concern into a proposal with permissions, resources and a clear first phase. Effective courage prepares a route for others to participate.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"],"refs":["Nehemiah 2:1","Nehemiah 2:10","Nehemiah 2:11","Nehemiah 2:12","Nehemiah 2:13","Nehemiah 2:14","Nehemiah 2:15","Nehemiah 2:16","Nehemiah 2:17","Nehemiah 2:18","Nehemiah 2:19","Nehemiah 2:2","Nehemiah 2:20","Nehemiah 2:3","Nehemiah 2:4","Nehemiah 2:5","Nehemiah 2:6","Nehemiah 2:7","Nehemiah 2:8","Nehemiah 2:9"]},{"historical_context":"Paul addresses a mixed Christian community in Rome through exhortations about worship, gifts, humility and relationships. His letter forms ethics within life under the Roman Empire.","spiritual_context":"Transformation begins with renewed thinking and becomes visible in hospitality, service and peace. Gifts are diverse but directed toward the good of the whole.","present_day_context":"Disrupt conformity by changing incentives and habits, not just language. Make room for different talents and respond to hostility without duplicating it.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx","https://www.sefaria.org/topics/midrash"],"refs":["Romans 12:1","Romans 12:10","Romans 12:11","Romans 12:12","Romans 12:13","Romans 12:14","Romans 12:15","Romans 12:16","Romans 12:17","Romans 12:18","Romans 12:19","Romans 12:2","Romans 12:20","Romans 12:21","Romans 12:3","Romans 12:4","Romans 12:5","Romans 12:6","Romans 12:7","Romans 12:8","Romans 12:9"]},{"historical_context":"Proverbs gathers compact wisdom sayings about trade, speech, integrity, generosity and public life. Their terse form teaches patterns rather than guaranteeing automatic outcomes.","spiritual_context":"Honest measures, trustworthy words and care for neighbors are spiritual concerns. Moral credibility matters more than the appearance of success.","present_day_context":"Disrupt a dishonest norm with transparent prices, fair processes and accountable decisions. Reputation is built in ordinary repeated choices.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Proverbs 11:1","Proverbs 11:10","Proverbs 11:11","Proverbs 11:12","Proverbs 11:13","Proverbs 11:14","Proverbs 11:15","Proverbs 11:16","Proverbs 11:17","Proverbs 11:18","Proverbs 11:19","Proverbs 11:2","Proverbs 11:20","Proverbs 11:21","Proverbs 11:22","Proverbs 11:23","Proverbs 11:24","Proverbs 11:25","Proverbs 11:26","Proverbs 11:27","Proverbs 11:28","Proverbs 11:29","Proverbs 11:3","Proverbs 11:30","Proverbs 11:31","Proverbs 11:4","Proverbs 11:5","Proverbs 11:6","Proverbs 11:7","Proverbs 11:8","Proverbs 11:9"]},{"historical_context":"Psalm 23 uses shepherd and host imagery familiar in the ancient Levant. As poetry, its metaphors describe care, danger and belonging rather than a map of dated events.","spiritual_context":"Trust does not eliminate valleys; it describes companionship through them. The image of a prepared table brings dignity into a threatened setting.","present_day_context":"Healthy leadership makes people safer in hard seasons. Ask whom your decisions shelter and whether your presence brings steadiness rather than fear.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Psalms 23:1","Psalms 23:2","Psalms 23:3","Psalms 23:4","Psalms 23:5","Psalms 23:6"]},{"historical_context":"Psalm 78 is a teaching psalm that retells community memory for a coming generation. Collective stories served an educational role in Israel''s worship.","spiritual_context":"The psalm warns that the next generation can inherit institutions without understanding their purpose. Remembrance is presented as a duty of formation.","present_day_context":"Record lessons from failures and victories, then teach them simply. An organization becomes durable when newcomers understand the reason behind its practices.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Psalms 78:1","Psalms 78:2","Psalms 78:3","Psalms 78:4","Psalms 78:5","Psalms 78:6","Psalms 78:7","Psalms 78:8"]},{"historical_context":"Revelation presents apocalyptic images of renewed creation and a holy city. Its symbolism draws from prophetic Scripture; it is not a literal architectural blueprint or a dated archaeology report.","spiritual_context":"The vision directs hope toward God''s restoration, justice and presence. Courage today is sustained by a horizon larger than present injustice.","present_day_context":"Work for truthful, healing communities now without pretending you can manufacture the final kingdom yourself. Hope can energize patient service.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://theharbingerbook.com/the-harbinger/","https://www.sefaria.org/topics/midrash"],"refs":["Revelation 21:1","Revelation 21:10","Revelation 21:11","Revelation 21:12","Revelation 21:13","Revelation 21:14","Revelation 21:15","Revelation 21:16","Revelation 21:17","Revelation 21:18","Revelation 21:19","Revelation 21:2","Revelation 21:20","Revelation 21:21","Revelation 21:22","Revelation 21:23","Revelation 21:24","Revelation 21:25","Revelation 21:26","Revelation 21:27","Revelation 21:3","Revelation 21:4","Revelation 21:5","Revelation 21:6","Revelation 21:7","Revelation 21:8","Revelation 21:9"]},{"historical_context":"Ruth begins amid migration, widowhood and food insecurity. Family obligation and later gleaning customs shape the choices available to Naomi and Ruth.","spiritual_context":"Ruth''s loyalty carries moral weight because it is costly and practical. In this story, faithfulness is expressed through presence and commitment during uncertainty.","present_day_context":"Do not underestimate the public consequences of small private acts of loyalty. Strong communities grow when vulnerable people are not left to manage loss alone.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash","https://adfonteslibrary.org/work-st-josephus-antiquities-1"],"refs":["Ruth 1:1","Ruth 1:10","Ruth 1:11","Ruth 1:12","Ruth 1:13","Ruth 1:14","Ruth 1:15","Ruth 1:16","Ruth 1:17","Ruth 1:18","Ruth 1:19","Ruth 1:2","Ruth 1:20","Ruth 1:21","Ruth 1:22","Ruth 1:3","Ruth 1:4","Ruth 1:5","Ruth 1:6","Ruth 1:7","Ruth 1:8","Ruth 1:9"]},{"historical_context":"Samuel''s visit to Jesse''s household takes place during a contested monarchy under Saul. Anointing marks David for a future role, even while daily life continues.","spiritual_context":"The narrative challenges judgments based only on visible stature. The gap between calling and office is a place for character to develop.","present_day_context":"Assess potential beyond charisma or appearance. Invest in habits and skill before demanding recognition.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://adfonteslibrary.org/work-st-josephus-antiquities-1","https://www.sefaria.org/topics/midrash"],"refs":["1 Samuel 16:1","1 Samuel 16:10","1 Samuel 16:11","1 Samuel 16:12","1 Samuel 16:13","1 Samuel 16:14","1 Samuel 16:15","1 Samuel 16:16","1 Samuel 16:17","1 Samuel 16:18","1 Samuel 16:19","1 Samuel 16:2","1 Samuel 16:20","1 Samuel 16:21","1 Samuel 16:22","1 Samuel 16:23","1 Samuel 16:3","1 Samuel 16:4","1 Samuel 16:5","1 Samuel 16:6","1 Samuel 16:7","1 Samuel 16:8","1 Samuel 16:9"]},{"historical_context":"The account depicts Moses hearing disputes continually while his father-in-law Jethro observes the burden. Delegated judging was a social and administrative question, not merely a private spiritual discipline.","spiritual_context":"Wise counsel corrects a leader who cannot carry everything alone. Sharing responsibility protects both the people and the leader from exhaustion.","present_day_context":"If every decision stops at your desk, establish clear authority levels and train trustworthy people. Sustainable impact is often built through systems, not heroic overwork.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://answersingenesis.org/archaeology/fact-checking-bible/","https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx"],"refs":["Exodus 18:13","Exodus 18:14","Exodus 18:15","Exodus 18:16","Exodus 18:17","Exodus 18:18","Exodus 18:19","Exodus 18:20","Exodus 18:21","Exodus 18:22","Exodus 18:23","Exodus 18:24","Exodus 18:25","Exodus 18:26","Exodus 18:27"]},{"historical_context":"The apostles speak before Jerusalem''s authorities as the early community navigates pressure and internal economic responsibilities. The text places bold speech beside shared resources.","spiritual_context":"Courage is rooted in witness rather than social status, while generosity gives the message visible substance. Public conviction and inward integrity belong together.","present_day_context":"Speak thoughtfully for what is right even when your credentials are questioned. Match words with practical commitments that help others flourish.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash","https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"],"refs":["Acts 4:1","Acts 4:10","Acts 4:11","Acts 4:12","Acts 4:13","Acts 4:14","Acts 4:15","Acts 4:16","Acts 4:17","Acts 4:18","Acts 4:19","Acts 4:2","Acts 4:20","Acts 4:21","Acts 4:22","Acts 4:23","Acts 4:24","Acts 4:25","Acts 4:26","Acts 4:27","Acts 4:28","Acts 4:29","Acts 4:3","Acts 4:30","Acts 4:31","Acts 4:32","Acts 4:33","Acts 4:34","Acts 4:35","Acts 4:36","Acts 4:37","Acts 4:4","Acts 4:5","Acts 4:6","Acts 4:7","Acts 4:8","Acts 4:9"]},{"historical_context":"The burning-bush narrative presents Moses, once connected to Egypt''s royal household, as a shepherd in Midian. Divine names and liberation language sit within the book''s larger memory of enslavement.","spiritual_context":"The call begins with attention to suffering and a commission that confronts oppressive power. Moses'' hesitations do not cancel the task but become part of his preparation.","present_day_context":"Notice a problem people have normalized. Ask what resources, relationships and courage would be needed to address it without treating affected people as a project.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://adfonteslibrary.org/work-st-josephus-antiquities-1","https://www.sefaria.org/topics/midrash"],"refs":["Exodus 3:1","Exodus 3:10","Exodus 3:11","Exodus 3:12","Exodus 3:13","Exodus 3:14","Exodus 3:15","Exodus 3:16","Exodus 3:17","Exodus 3:18","Exodus 3:19","Exodus 3:2","Exodus 3:20","Exodus 3:21","Exodus 3:22","Exodus 3:3","Exodus 3:4","Exodus 3:5","Exodus 3:6","Exodus 3:7","Exodus 3:8","Exodus 3:9"]},{"historical_context":"The Carmel account stands within the conflict over royal support of Baal worship during Ahab''s reign. The narrative is a theological contest and should not be confused with evidence for every reported miracle.","spiritual_context":"Elijah''s challenge demands a choice about allegiance and integrity. The story pairs courage with prayer and refuses a comfortable double loyalty.","present_day_context":"Identify a value your group speaks about but routinely compromises. Model it openly with humility, without turning conviction into hostility toward people.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash","https://answersingenesis.org/archaeology/fact-checking-bible/"],"refs":["1 Kings 18:1","1 Kings 18:10","1 Kings 18:11","1 Kings 18:12","1 Kings 18:13","1 Kings 18:14","1 Kings 18:15","1 Kings 18:16","1 Kings 18:17","1 Kings 18:18","1 Kings 18:19","1 Kings 18:2","1 Kings 18:20","1 Kings 18:21","1 Kings 18:22","1 Kings 18:23","1 Kings 18:24","1 Kings 18:25","1 Kings 18:26","1 Kings 18:27","1 Kings 18:28","1 Kings 18:29","1 Kings 18:3","1 Kings 18:30","1 Kings 18:31","1 Kings 18:32","1 Kings 18:33","1 Kings 18:34","1 Kings 18:35","1 Kings 18:36","1 Kings 18:37","1 Kings 18:38","1 Kings 18:39","1 Kings 18:4","1 Kings 18:40","1 Kings 18:41","1 Kings 18:42","1 Kings 18:43","1 Kings 18:44","1 Kings 18:45","1 Kings 18:46","1 Kings 18:5","1 Kings 18:6","1 Kings 18:7","1 Kings 18:8","1 Kings 18:9"]},{"historical_context":"The chapter begins with Midianite pressure on Israel''s food supply and survival. Raiding and crop destruction were severe threats in an agrarian society, shaping how the oppressed community behaved.","spiritual_context":"Before Gideon receives a task, the narrative makes collective suffering visible. Spiritual discernment should begin with attention to people''s real conditions, not slogans.","present_day_context":"When a community is under pressure, investigate the material problem as carefully as the morale problem. Courage can begin with honest diagnosis.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.thetorah.com/article/questioning-gods-call-moses-versus-gideon","https://www.asor.org/news/2019/03/nea82_1-toc/"],"refs":["Judges 6:1","Judges 6:10","Judges 6:2","Judges 6:3","Judges 6:4","Judges 6:5","Judges 6:6","Judges 6:7","Judges 6:8","Judges 6:9"]},{"historical_context":"The court narrative places Judean youths within the world of Babylonian imperial education and service. It speaks to identity and adaptation under foreign political power.","spiritual_context":"Daniel and his companions negotiate participation without surrendering every conviction. The spiritual issue is thoughtful fidelity, not withdrawal from learning.","present_day_context":"You can learn an institution''s language and still retain integrity. Choose which norms help your purpose and which require respectful resistance.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"],"refs":["Daniel 1:1","Daniel 1:10","Daniel 1:11","Daniel 1:12","Daniel 1:13","Daniel 1:14","Daniel 1:15","Daniel 1:16","Daniel 1:17","Daniel 1:18","Daniel 1:19","Daniel 1:2","Daniel 1:20","Daniel 1:21","Daniel 1:3","Daniel 1:4","Daniel 1:5","Daniel 1:6","Daniel 1:7","Daniel 1:8","Daniel 1:9"]},{"historical_context":"The footwashing scene occurs during the final meal in John''s Gospel, in a culture where washing dusty feet was associated with hospitality and low-status service.","spiritual_context":"Jesus redefines greatness through an act of humble service. The teacher''s authority is not reduced by serving; it is expressed through it.","present_day_context":"If you supervise others, take responsibility for the difficult work you usually delegate. Service should become a standard of leadership, not an occasional performance.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash","https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx"],"refs":["John 13:1","John 13:10","John 13:11","John 13:12","John 13:13","John 13:14","John 13:15","John 13:16","John 13:17","John 13:2","John 13:3","John 13:4","John 13:5","John 13:6","John 13:7","John 13:8","John 13:9"]},{"historical_context":"The Jericho narrative describes an ancient fortified city and a highly stylized sequence of marching, trumpets and shouting. Archaeological interpretations of Jericho''s settlement history are contested and should be distinguished from the text''s theological claims.","spiritual_context":"The story portrays obedience and communal coordination in an unfamiliar strategy. It should not be treated as permission to imitate ancient warfare in modern civic or religious life.","present_day_context":"Sometimes a stubborn obstacle needs patient preparation and coordinated action more than noise. Measure success by faithfulness and the welfare of others, not domination.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://answersingenesis.org/archaeology/fact-checking-bible/","https://www.asor.org/news/2019/03/nea82_1-toc/"],"refs":["Joshua 6:1","Joshua 6:10","Joshua 6:11","Joshua 6:12","Joshua 6:13","Joshua 6:14","Joshua 6:15","Joshua 6:16","Joshua 6:17","Joshua 6:18","Joshua 6:19","Joshua 6:2","Joshua 6:20","Joshua 6:21","Joshua 6:22","Joshua 6:23","Joshua 6:24","Joshua 6:25","Joshua 6:26","Joshua 6:27","Joshua 6:3","Joshua 6:4","Joshua 6:5","Joshua 6:6","Joshua 6:7","Joshua 6:8","Joshua 6:9"]},{"historical_context":"The letter moves from theological identity to communal habits: unity, maturity, truth-telling and renewed conduct. The language addresses a shared life, not isolated self-improvement.","spiritual_context":"Different forms of service help equip the community toward maturity. Growth is measured in truth, love and cooperation rather than position alone.","present_day_context":"Equip others to perform meaningful work instead of keeping them dependent on you. Speak accurately, repair conflict and distribute responsibility.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx","https://www.sefaria.org/topics/midrash"],"refs":["Ephesians 4:1","Ephesians 4:10","Ephesians 4:11","Ephesians 4:12","Ephesians 4:13","Ephesians 4:14","Ephesians 4:15","Ephesians 4:16","Ephesians 4:17","Ephesians 4:18","Ephesians 4:19","Ephesians 4:2","Ephesians 4:20","Ephesians 4:21","Ephesians 4:22","Ephesians 4:23","Ephesians 4:24","Ephesians 4:25","Ephesians 4:26","Ephesians 4:27","Ephesians 4:28","Ephesians 4:29","Ephesians 4:3","Ephesians 4:30","Ephesians 4:31","Ephesians 4:32","Ephesians 4:4","Ephesians 4:5","Ephesians 4:6","Ephesians 4:7","Ephesians 4:8","Ephesians 4:9"]},{"historical_context":"The lion''s-den narrative involves royal bureaucracy, legal decrees and public reputation in a court setting. Its literary structure sharpens the conflict between personal devotion and political pressure.","spiritual_context":"Daniel''s established prayer practice matters before the crisis arrives. Faithfulness is formed over time, not manufactured at the final moment.","present_day_context":"Build routines of integrity now, while decisions are still quiet. The habits you keep under normal pressure determine how you act under intense scrutiny.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"],"refs":["Daniel 6:1","Daniel 6:10","Daniel 6:11","Daniel 6:12","Daniel 6:13","Daniel 6:14","Daniel 6:15","Daniel 6:16","Daniel 6:17","Daniel 6:18","Daniel 6:19","Daniel 6:2","Daniel 6:20","Daniel 6:21","Daniel 6:22","Daniel 6:23","Daniel 6:24","Daniel 6:25","Daniel 6:26","Daniel 6:27","Daniel 6:28","Daniel 6:3","Daniel 6:4","Daniel 6:5","Daniel 6:6","Daniel 6:7","Daniel 6:8","Daniel 6:9"]},{"historical_context":"The narrator interprets Israel''s recurring troubles through covenant faithfulness, generational forgetting and the rise of deliverers. This is the book''s theological framework, not a neutral archaeological chronology.","spiritual_context":"The cycle of drift, distress, rescue and relapse raises the question of formation. Extraordinary intervention cannot replace habits that teach the next generation to remember.","present_day_context":"If a good initiative declines after its founder leaves, investigate the habits and structures you failed to pass on. Train successors, not just admirers.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.asor.org/news/2019/03/nea82_1-toc/","https://www.sefaria.org/topics/midrash"],"refs":["Judges 2:1","Judges 2:10","Judges 2:11","Judges 2:12","Judges 2:13","Judges 2:14","Judges 2:15","Judges 2:16","Judges 2:17","Judges 2:18","Judges 2:19","Judges 2:2","Judges 2:20","Judges 2:21","Judges 2:22","Judges 2:23","Judges 2:3","Judges 2:4","Judges 2:5","Judges 2:6","Judges 2:7","Judges 2:8","Judges 2:9"]},{"historical_context":"The opening of Job is wisdom narrative, introducing a respected man and a sequence of devastating losses. Its literary form differs from a dated royal chronicle.","spiritual_context":"Job''s first response offers a model of worship under uncertainty without explaining away suffering. The book later challenges simplistic stories about why people suffer.","present_day_context":"When plans collapse, resist instant explanations about someone else''s hardship. Offer presence, practical support and space for honest questions.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Job 1:1","Job 1:10","Job 1:11","Job 1:12","Job 1:13","Job 1:14","Job 1:15","Job 1:16","Job 1:17","Job 1:18","Job 1:19","Job 1:2","Job 1:20","Job 1:21","Job 1:22","Job 1:3","Job 1:4","Job 1:5","Job 1:6","Job 1:7","Job 1:8","Job 1:9"]},{"historical_context":"The parable uses household stewardship and entrusted resources, familiar social images in the ancient Mediterranean. Its details are part of a teaching story, not a modern investment manual.","spiritual_context":"Entrusted ability creates responsibility, but the parable must be read within Matthew''s larger teaching about watchfulness and accountability.","present_day_context":"Use what is genuinely entrusted to you with care, learning and courage. Measure fruit by responsible service, not simply accumulating wealth or status.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash","https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx"],"refs":["Matthew 25:14","Matthew 25:15","Matthew 25:16","Matthew 25:17","Matthew 25:18","Matthew 25:19","Matthew 25:20","Matthew 25:21","Matthew 25:22","Matthew 25:23","Matthew 25:24","Matthew 25:25","Matthew 25:26","Matthew 25:27","Matthew 25:28","Matthew 25:29","Matthew 25:30"]},{"historical_context":"The patriarchal narrative places Abram in a world of households, kinship ties, migration and promised land. Later Jewish interpretation expands the story, but those expansions should not be mistaken for the wording of Genesis.","spiritual_context":"The call to Abram links blessing with becoming a blessing to other families. Faith here involves movement, trust and an orientation beyond personal security.","present_day_context":"A meaningful assignment may begin without a complete map. Identify the first ethical step you can take with what you know, and prepare to learn along the way.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://adfonteslibrary.org/work-st-josephus-antiquities-1","https://www.sefaria.org/topics/midrash"],"refs":["Genesis 12:1","Genesis 12:2","Genesis 12:3","Genesis 12:4","Genesis 12:5","Genesis 12:6","Genesis 12:7","Genesis 12:8","Genesis 12:9"]},{"historical_context":"The royal promise to David follows the establishment of a capital and a conversation about temple building. The distinction between a physical house and a lasting dynasty drives the narrative.","spiritual_context":"God''s promise reframes David''s desire to build as part of a larger purpose he cannot control. Legacy is more than constructing visible monuments.","present_day_context":"A mature leader knows when to build, when to prepare others and when not to own the final outcome. Design work that can outlive your personal presence.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://adfonteslibrary.org/work-st-josephus-antiquities-1"],"refs":["2 Samuel 7:1","2 Samuel 7:10","2 Samuel 7:11","2 Samuel 7:12","2 Samuel 7:13","2 Samuel 7:14","2 Samuel 7:15","2 Samuel 7:16","2 Samuel 7:17","2 Samuel 7:18","2 Samuel 7:19","2 Samuel 7:2","2 Samuel 7:20","2 Samuel 7:21","2 Samuel 7:22","2 Samuel 7:23","2 Samuel 7:24","2 Samuel 7:25","2 Samuel 7:26","2 Samuel 7:27","2 Samuel 7:28","2 Samuel 7:29","2 Samuel 7:3","2 Samuel 7:4","2 Samuel 7:5","2 Samuel 7:6","2 Samuel 7:7","2 Samuel 7:8","2 Samuel 7:9"]},{"historical_context":"The Samaritan parable crosses a deeply charged boundary between neighboring communities. It asks a lawyer to reconsider the scope of ''neighbor'' through a story of costly assistance.","spiritual_context":"Compassion is measured by action across social difference. The expected insider does not become the moral example; the outsider does.","present_day_context":"Identify who falls outside your normal circle of care. Build a response that meets actual needs without requiring agreement on every belief first.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Luke 10:25","Luke 10:26","Luke 10:27","Luke 10:28","Luke 10:29","Luke 10:30","Luke 10:31","Luke 10:32","Luke 10:33","Luke 10:34","Luke 10:35","Luke 10:36","Luke 10:37"]},{"historical_context":"The spy narrative follows Israel near the land of Canaan, with scouts observing settlements, crops and inhabitants. The report combines real observations with disputed conclusions about capacity and danger.","spiritual_context":"The story distinguishes assessing risk from surrendering initiative to fear. Caleb''s confidence is linked to trust and action, not pretending opposition does not exist.","present_day_context":"Gather accurate facts before entering a difficult assignment, but do not let the loudest fearful interpretation become the only possible future.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://answersingenesis.org/archaeology/fact-checking-bible/"],"refs":["Numbers 13:1","Numbers 13:10","Numbers 13:11","Numbers 13:12","Numbers 13:13","Numbers 13:14","Numbers 13:15","Numbers 13:16","Numbers 13:17","Numbers 13:18","Numbers 13:19","Numbers 13:2","Numbers 13:20","Numbers 13:21","Numbers 13:22","Numbers 13:23","Numbers 13:24","Numbers 13:25","Numbers 13:26","Numbers 13:27","Numbers 13:28","Numbers 13:29","Numbers 13:3","Numbers 13:30","Numbers 13:31","Numbers 13:32","Numbers 13:33","Numbers 13:4","Numbers 13:5","Numbers 13:6","Numbers 13:7","Numbers 13:8","Numbers 13:9"]},{"historical_context":"The story is set at the Persian court, where access to the king is governed by status and protocol. Literary and historical debates exist about how directly the narrative maps onto court records.","spiritual_context":"Mordecai challenges Esther to consider responsibility within an unexpected position. Courage is pictured as discernment under real personal risk.","present_day_context":"Use access and influence to defend people who have less of both. Think through the consequences, consult allies and act when silence would be costly.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.sefaria.org/topics/midrash"],"refs":["Esther 4:1","Esther 4:10","Esther 4:11","Esther 4:12","Esther 4:13","Esther 4:14","Esther 4:15","Esther 4:16","Esther 4:17","Esther 4:2","Esther 4:3","Esther 4:4","Esther 4:5","Esther 4:6","Esther 4:7","Esther 4:8","Esther 4:9"]},{"historical_context":"The three companies receive trumpets, jars and torches in a coordinated nighttime attack. The text describes confusion within the opposing camp; it does not establish a timeless military technique.","spiritual_context":"Unity, timing and surprise matter in the biblical narrative, while the narrator credits deliverance to God. The passage does not justify manipulating people in ordinary leadership.","present_day_context":"A worthwhile disruption may depend on simple tools used together with clarity and discipline. Coordinate the team and choose methods consistent with the good you want to achieve.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://www.thetorah.com/article/questioning-gods-call-moses-versus-gideon","https://www.asor.org/news/2019/03/nea82_1-toc/"],"refs":["Judges 7:16","Judges 7:17","Judges 7:18","Judges 7:19","Judges 7:20","Judges 7:21","Judges 7:22"]},{"historical_context":"The valley confrontation between Israel and Philistia is narrated through champions, military camps and an outsized threat. Different ancient textual witnesses vary in some details of the David narrative.","spiritual_context":"David''s response questions an atmosphere that has normalized fear. Confidence is tied to remembered experience and devotion, not denial of danger.","present_day_context":"When everyone assumes a problem cannot be solved, examine the assumption. Bring evidence from earlier learning and select a proportionate, ethical strategy.","research_note":"Original Instructor editorial passage guide. Historical background, literary interpretation and devotional application are distinct; archaeology does not independently verify each narrated episode.","source_links":["https://adfonteslibrary.org/work-st-josephus-antiquities-1","https://www.sefaria.org/topics/midrash"],"refs":["1 Samuel 17:1","1 Samuel 17:10","1 Samuel 17:11","1 Samuel 17:12","1 Samuel 17:13","1 Samuel 17:14","1 Samuel 17:15","1 Samuel 17:16","1 Samuel 17:17","1 Samuel 17:18","1 Samuel 17:19","1 Samuel 17:2","1 Samuel 17:20","1 Samuel 17:21","1 Samuel 17:22","1 Samuel 17:23","1 Samuel 17:24","1 Samuel 17:25","1 Samuel 17:26","1 Samuel 17:27","1 Samuel 17:28","1 Samuel 17:29","1 Samuel 17:3","1 Samuel 17:30","1 Samuel 17:31","1 Samuel 17:32","1 Samuel 17:33","1 Samuel 17:34","1 Samuel 17:35","1 Samuel 17:36","1 Samuel 17:37","1 Samuel 17:38","1 Samuel 17:39","1 Samuel 17:4","1 Samuel 17:40","1 Samuel 17:41","1 Samuel 17:42","1 Samuel 17:43","1 Samuel 17:44","1 Samuel 17:45","1 Samuel 17:46","1 Samuel 17:47","1 Samuel 17:48","1 Samuel 17:49","1 Samuel 17:5","1 Samuel 17:50","1 Samuel 17:51","1 Samuel 17:52","1 Samuel 17:53","1 Samuel 17:54","1 Samuel 17:55","1 Samuel 17:56","1 Samuel 17:57","1 Samuel 17:58","1 Samuel 17:6","1 Samuel 17:7","1 Samuel 17:8","1 Samuel 17:9"]}]'::jsonb)
 as grp(historical_context text,spiritual_context text,present_day_context text,
  research_note text,source_links jsonb,refs jsonb)
cross join lateral jsonb_array_elements_text(grp.refs) verse(value)
on conflict(reference) do update
 set historical_context=excluded.historical_context,spiritual_context=excluded.spiritual_context,
 present_day_context=excluded.present_day_context,research_note=excluded.research_note,
 source_links=excluded.source_links,updated_at=now();

-- Hidden quiz questions and answers are held only in the private server-side bank.
-- Never check prize answer keys or current hidden locations into public source control.

CREATE OR REPLACE FUNCTION public.ensure_quarterly_verse_quests()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_quarter date := date_trunc('quarter', now() at time zone 'Africa/Douala')::date;
 v_count integer;
begin
 perform pg_advisory_xact_lock(hashtextextended('fullcircle:verse-quest-quarter:'||v_quarter::text,0));
 select count(*) into v_count from public.quarterly_verse_quests where quarter_start=v_quarter;
 if v_count>0 then return v_count; end if;
 if (select count(*) from public.verse_quest_templates where enabled)<30 then return 0; end if;
 insert into public.quarterly_verse_quests (
   quarter_start,reference,question,choices,correct_answer,explanation,
   prize_type,prize_quantity,relic_slug
 )
 select v_quarter,reference,question,choices,correct_answer,explanation,
 case when rn<=3 then 'fcx_ticket' when rn<=15 then 'relic' else 'denarii' end,
 case when rn<=15 then 1 when rn%3=0 then 1500 when rn%3=1 then 500 else 1000 end,
 case when rn between 4 and 15 then
   (array['shield-of-faith','boomerang','freeze-timer','skip','reveal-reference','sword-goliath'])[1+((rn-4)%6)]
 else null end
 from (
   with latest_reading as (
     select highlighted_verses from public.daily_narratives
     where narrative_date <= (now() at time zone 'Africa/Douala')::date
     order by narrative_date desc limit 1
   ),
   anchor as (
     select template.* from public.verse_quest_templates template
     join latest_reading latest on exists (
       select 1 from jsonb_array_elements(coalesce(latest.highlighted_verses,'[]'::jsonb)) verse
       where verse->>'reference'=template.reference
     )
     where template.enabled order by random() limit 1
   ),
   others as (
     select template.* from public.verse_quest_templates template
     where template.enabled and not exists (select 1 from anchor where anchor.reference=template.reference)
     order by random() limit (30-(select count(*) from anchor))
   ),
   candidates as (
     select true as is_anchor,anchor.* from anchor
     union all
     select false as is_anchor,others.* from others
   )
   select candidates.*, row_number() over(order by is_anchor desc,random()) rn from candidates
 ) picks;
 get diagnostics v_count=row_count;
 return v_count;
end $function$;
revoke all on function public.ensure_quarterly_verse_quests() from public,anon,authenticated;
grant execute on function public.ensure_quarterly_verse_quests() to service_role;
CREATE OR REPLACE FUNCTION public.get_quarterly_verse_quests(p_references text[])
 RETURNS TABLE(id uuid, reference text, question text, choices jsonb, prize_label text, attempted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_quarter date:=date_trunc('quarter',now() at time zone 'Africa/Douala')::date;
begin
 if auth.uid() is null or p_references is null or cardinality(p_references)>180
 then return; end if;
 perform public.ensure_quarterly_verse_quests();
 return query
 select q.id,q.reference,q.question,q.choices,
 case when q.prize_type='fcx_ticket' then 'A free FCX ticket'
      when q.prize_type='relic' then 'A mystery relic'
      else q.prize_quantity::text||' Denarii' end,
 exists(select 1 from public.quarterly_verse_quest_attempts a where a.quest_id=q.id and a.user_id=auth.uid())
 from public.quarterly_verse_quests q
 where q.quarter_start=v_quarter and q.winner_user_id is null
   and q.reference = any(p_references)
 order by q.reference;
end $function$;
revoke all on function public.get_quarterly_verse_quests(text[]) from public,anon;
grant execute on function public.get_quarterly_verse_quests(text[]) to authenticated,service_role;
CREATE OR REPLACE FUNCTION public.answer_quarterly_verse_quest(p_quest_id uuid, p_answer text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_user uuid:=auth.uid();
 v_quarter date:=date_trunc('quarter',now() at time zone 'Africa/Douala')::date;
 v_quest public.quarterly_verse_quests%rowtype;
 v_correct boolean;
 v_relic public.relic_types%rowtype;
 v_event public.fcx_events%rowtype;
 v_registered boolean:=false;
 v_prize text;
begin
 if v_user is null then raise exception 'Sign in to take part in Bible discoveries.'; end if;
 if p_answer is null or length(trim(p_answer))<1 or length(p_answer)>120
 then raise exception 'Choose an answer before submitting.'; end if;
 -- Lock the prize itself; simultaneous correct answers serialize here.
 select * into v_quest from public.quarterly_verse_quests
 where id=p_quest_id and quarter_start=v_quarter for update;
 if not found then return jsonb_build_object('status','unavailable','message','This discovery is no longer active.'); end if;
 if v_quest.winner_user_id is not null then
   return jsonb_build_object('status','claimed','message','Another reader found this prize first.');
 end if;
 if exists(select 1 from public.quarterly_verse_quest_attempts where quest_id=p_quest_id and user_id=v_user)
 then return jsonb_build_object('status','already_attempted','message','You have already answered this discovery.'); end if;
 v_correct := lower(regexp_replace(trim(p_answer),'[^[:alnum:]]','','g'))
    =lower(regexp_replace(trim(v_quest.correct_answer),'[^[:alnum:]]','','g'));
 insert into public.quarterly_verse_quest_attempts(quest_id,user_id,submitted_answer,is_correct)
 values(p_quest_id,v_user,p_answer,v_correct);
 if not v_correct then
   return jsonb_build_object('status','incorrect','message','That answer was not correct. This discovery allows one attempt per reader.');
 end if;
 update public.quarterly_verse_quests set winner_user_id=v_user,claimed_at=clock_timestamp() where id=p_quest_id;
 if v_quest.prize_type='denarii' then
   insert into public.denarii_ledger_entries(user_id,amount,source_type,source_reference,description)
   values(v_user,v_quest.prize_quantity,'verse_quest',p_quest_id::text,'First-finder quarterly Scripture reward');
   v_prize:=v_quest.prize_quantity::text||' Denarii';
 elsif v_quest.prize_type='relic' then
   select * into v_relic from public.relic_types where slug=v_quest.relic_slug and is_active=true;
   if not found then raise exception 'This reward relic is not available. No prize was claimed.'; end if;
   insert into public.relic_inventory(user_id,relic_type_id,quantity,source_description)
   values(v_user,v_relic.id,v_quest.prize_quantity,'Quarterly Scripture discovery '||p_quest_id::text)
   on conflict(user_id,relic_type_id) do update set quantity=public.relic_inventory.quantity+excluded.quantity;
   v_prize:=v_relic.name||' relic';
 else
   select * into v_event from public.fcx_events
   where is_active=true and event_date >= (now() at time zone 'Africa/Douala')::date
   order by event_date,id limit 1 for update;
   if found and not exists (select 1 from public.fcx_registrations where event_id=v_event.id and user_id=v_user)
      and (select count(*) from public.fcx_registrations where event_id=v_event.id)<v_event.capacity
   then
     insert into public.fcx_registrations(event_id,user_id,payment_source,added_by)
     values(v_event.id,v_user,'app',v_user);
     v_registered:=true;
     insert into public.quarterly_verse_fcx_awards(quest_id,user_id,event_id,status)
     values(p_quest_id,v_user,v_event.id,'registered');
   else
     insert into public.quarterly_verse_fcx_awards(quest_id,user_id,event_id,status)
     values(p_quest_id,v_user,null,'awaiting_event');
   end if;
   v_prize:=case when v_registered then 'A free FCX ticket — your registration is confirmed'
                else 'A free FCX ticket — awaiting the next available FCX event' end;
 end if;
 return jsonb_build_object('status','won','prize',v_prize,
    'message','Congratulations! You were the first reader to answer this hidden Scripture question correctly.',
    'explanation',v_quest.explanation,'fcx_registered',v_registered,
    'fcx_event_date',case when v_registered then v_event.event_date else null end);
end $function$;
revoke all on function public.answer_quarterly_verse_quest(uuid,text) from public,anon;
grant execute on function public.answer_quarterly_verse_quest(uuid,text) to authenticated,service_role;

-- Allow Scripture first-finder Denarii awards as a distinct audited ledger source.
alter table public.denarii_ledger_entries drop constraint if exists denarii_ledger_entries_source_type_check;
alter table public.denarii_ledger_entries add constraint denarii_ledger_entries_source_type_check
 check(source_type=any(array['game_level'::text,'game_blitz'::text,'quiz_reward'::text,'fortune_quiz_reward'::text,'relic_purchase'::text,'relic_reward'::text,'admin_adjustment'::text,'hint_purchase'::text,'answer_reveal'::text,'freezer_daily'::text,'freezer_weekly'::text,'attendance'::text,'arena_stake'::text,'arena_fee'::text,'arena_reward'::text,'mobile_money'::text,'campay_payment'::text,'notification_opt_in'::text,'challenge_submission'::text,'dove_question_cost'::text,'dove_question_reward'::text,'hidden_item_purchase'::text,'treasure_escrow'::text,'treasure_reward'::text,'treasure_refund'::text,'mine_penalty'::text,'mine_reward'::text,'player_number_purchase'::text,'fcx_ticket'::text,'verse_quest'::text]));

-- Supplementary Instructor Insights: major readings from every previously uncovered Bible book.
insert into public.instructor_verse_contexts(reference,historical_context,spiritual_context,present_day_context,research_note,source_links)
select verse.value, grp.historical_context,grp.spiritual_context,grp.present_day_context,grp.research_note,grp.source_links
from jsonb_to_recordset('[{"refs":["Leviticus 19:1","Leviticus 19:2","Leviticus 19:3","Leviticus 19:4","Leviticus 19:5","Leviticus 19:6","Leviticus 19:7","Leviticus 19:8","Leviticus 19:9","Leviticus 19:10","Leviticus 19:11","Leviticus 19:12","Leviticus 19:13","Leviticus 19:14","Leviticus 19:15","Leviticus 19:16","Leviticus 19:17","Leviticus 19:18","Leviticus 19:19","Leviticus 19:20","Leviticus 19:21","Leviticus 19:22","Leviticus 19:23","Leviticus 19:24","Leviticus 19:25","Leviticus 19:26","Leviticus 19:27","Leviticus 19:28","Leviticus 19:29","Leviticus 19:30","Leviticus 19:31","Leviticus 19:32","Leviticus 19:33","Leviticus 19:34","Leviticus 19:35","Leviticus 19:36","Leviticus 19:37"],"historical_context":"Leviticus 19 brings together worship practices, agricultural rules, commercial honesty and treatment of neighbors. The social world is covenant Israel, and its laws should be studied in literary and historical context before applying them today.","spiritual_context":"Holiness is portrayed through ordinary justice as well as ritual. The call to love one''s neighbor keeps devotion from becoming disconnected from public conduct.","present_day_context":"Set a high standard for fair dealing, truthful measurement and protection of the vulnerable. A culture of excellence begins with how people are treated when no one is watching.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["1 Chronicles 29:1","1 Chronicles 29:2","1 Chronicles 29:3","1 Chronicles 29:4","1 Chronicles 29:5","1 Chronicles 29:6","1 Chronicles 29:7","1 Chronicles 29:8","1 Chronicles 29:9","1 Chronicles 29:10","1 Chronicles 29:11","1 Chronicles 29:12","1 Chronicles 29:13","1 Chronicles 29:14","1 Chronicles 29:15","1 Chronicles 29:16","1 Chronicles 29:17","1 Chronicles 29:18","1 Chronicles 29:19","1 Chronicles 29:20","1 Chronicles 29:21","1 Chronicles 29:22","1 Chronicles 29:23","1 Chronicles 29:24","1 Chronicles 29:25","1 Chronicles 29:26","1 Chronicles 29:27","1 Chronicles 29:28","1 Chronicles 29:29","1 Chronicles 29:30"],"historical_context":"Chronicles retells Israel''s royal history with special attention to worship, the temple and communal contribution. Its emphases differ from those of Samuel and Kings and reflect a later historical perspective.","spiritual_context":"David''s public preparation for the temple is linked to voluntary giving and acknowledgement that resources ultimately belong to God.","present_day_context":"Plan for work that will outlast your term. Invite participation transparently and leave behind resources and people ready to build.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["2 Chronicles 7:1","2 Chronicles 7:2","2 Chronicles 7:3","2 Chronicles 7:4","2 Chronicles 7:5","2 Chronicles 7:6","2 Chronicles 7:7","2 Chronicles 7:8","2 Chronicles 7:9","2 Chronicles 7:10","2 Chronicles 7:11","2 Chronicles 7:12","2 Chronicles 7:13","2 Chronicles 7:14","2 Chronicles 7:15","2 Chronicles 7:16","2 Chronicles 7:17","2 Chronicles 7:18","2 Chronicles 7:19","2 Chronicles 7:20","2 Chronicles 7:21","2 Chronicles 7:22"],"historical_context":"The dedication of Solomon''s temple is narrated through sacrifice, celebration and covenant warnings. The account connects royal leadership and communal worship with responsibility for justice and fidelity.","spiritual_context":"The prayer-and-response motif refuses to treat a beautiful building as a substitute for humble obedience. Restoration involves repentance and changed direction.","present_day_context":"An impressive institution can still drift. Review the health of its people and practices, not only its facilities and public events.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Ezra 7:1","Ezra 7:2","Ezra 7:3","Ezra 7:4","Ezra 7:5","Ezra 7:6","Ezra 7:7","Ezra 7:8","Ezra 7:9","Ezra 7:10","Ezra 7:11","Ezra 7:12","Ezra 7:13","Ezra 7:14","Ezra 7:15","Ezra 7:16","Ezra 7:17","Ezra 7:18","Ezra 7:19","Ezra 7:20","Ezra 7:21","Ezra 7:22","Ezra 7:23","Ezra 7:24","Ezra 7:25","Ezra 7:26","Ezra 7:27","Ezra 7:28"],"historical_context":"Ezra''s mission unfolds in the Persian-period setting, when Judean communities negotiated imperial permission, local law and the rebuilding of communal life.","spiritual_context":"The text presents learning, practicing and teaching as a connected sequence. Faithful instruction requires the teacher to live what is taught.","present_day_context":"Before launching a reform, study the situation and train credible people. Authority becomes trustworthy when knowledge and conduct agree.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"]},{"refs":["Ecclesiastes 3:1","Ecclesiastes 3:2","Ecclesiastes 3:3","Ecclesiastes 3:4","Ecclesiastes 3:5","Ecclesiastes 3:6","Ecclesiastes 3:7","Ecclesiastes 3:8","Ecclesiastes 3:9","Ecclesiastes 3:10","Ecclesiastes 3:11","Ecclesiastes 3:12","Ecclesiastes 3:13","Ecclesiastes 3:14","Ecclesiastes 3:15","Ecclesiastes 3:16","Ecclesiastes 3:17","Ecclesiastes 3:18","Ecclesiastes 3:19","Ecclesiastes 3:20","Ecclesiastes 3:21","Ecclesiastes 3:22"],"historical_context":"Ecclesiastes belongs to the wisdom tradition and reflects on time, work, limitation and human uncertainty. Its poetic catalogue is not a forecast assigning a date to every event.","spiritual_context":"Recognizing seasons can deepen humility and patience without becoming an excuse for inaction. Wisdom notices when an approach no longer fits the moment.","present_day_context":"Discern what to begin, preserve or release. A thoughtful leader changes tactics when needed while remaining faithful to the mission.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Song of Solomon 2:1","Song of Solomon 2:2","Song of Solomon 2:3","Song of Solomon 2:4","Song of Solomon 2:5","Song of Solomon 2:6","Song of Solomon 2:7","Song of Solomon 2:8","Song of Solomon 2:9","Song of Solomon 2:10","Song of Solomon 2:11","Song of Solomon 2:12","Song of Solomon 2:13","Song of Solomon 2:14","Song of Solomon 2:15","Song of Solomon 2:16","Song of Solomon 2:17"],"historical_context":"The Song is ancient love poetry rich in garden, animal and seasonal imagery. Jewish and Christian traditions have also read it allegorically, but its poetic voice should not be flattened into a single interpretation.","spiritual_context":"Faithful love includes delight, attentiveness and care; spiritual allegories are later interpretive traditions rather than the only meaning of the text.","present_day_context":"Respect mutuality and boundaries in close relationships. Healthy personal commitments sustain, rather than compete with, worthwhile public service.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Lamentations 3:1","Lamentations 3:2","Lamentations 3:3","Lamentations 3:4","Lamentations 3:5","Lamentations 3:6","Lamentations 3:7","Lamentations 3:8","Lamentations 3:9","Lamentations 3:10","Lamentations 3:11","Lamentations 3:12","Lamentations 3:13","Lamentations 3:14","Lamentations 3:15","Lamentations 3:16","Lamentations 3:17","Lamentations 3:18","Lamentations 3:19","Lamentations 3:20","Lamentations 3:21","Lamentations 3:22","Lamentations 3:23","Lamentations 3:24","Lamentations 3:25","Lamentations 3:26","Lamentations 3:27","Lamentations 3:28","Lamentations 3:29","Lamentations 3:30","Lamentations 3:31","Lamentations 3:32","Lamentations 3:33","Lamentations 3:34","Lamentations 3:35","Lamentations 3:36","Lamentations 3:37","Lamentations 3:38","Lamentations 3:39","Lamentations 3:40","Lamentations 3:41","Lamentations 3:42","Lamentations 3:43","Lamentations 3:44","Lamentations 3:45","Lamentations 3:46","Lamentations 3:47","Lamentations 3:48","Lamentations 3:49","Lamentations 3:50","Lamentations 3:51","Lamentations 3:52","Lamentations 3:53","Lamentations 3:54","Lamentations 3:55","Lamentations 3:56","Lamentations 3:57","Lamentations 3:58","Lamentations 3:59","Lamentations 3:60","Lamentations 3:61","Lamentations 3:62","Lamentations 3:63","Lamentations 3:64","Lamentations 3:65","Lamentations 3:66"],"historical_context":"Lamentations is poetry shaped by the destruction of Jerusalem and the experience of grief after catastrophe. Its first-person voice makes room for bewilderment as well as hope.","spiritual_context":"Hope arises without pretending devastation was small. Remembered mercy becomes a way to continue speaking honestly before God.","present_day_context":"When a community suffers loss, make space for lament before offering solutions. Courage can look like rebuilding patiently with people who are still grieving.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"]},{"refs":["Hosea 6:1","Hosea 6:2","Hosea 6:3","Hosea 6:4","Hosea 6:5","Hosea 6:6","Hosea 6:7","Hosea 6:8","Hosea 6:9","Hosea 6:10","Hosea 6:11"],"historical_context":"Hosea addresses Israel through covenant language and critique of inconsistent worship. Prophetic imagery interprets social and political failure in the light of loyalty to God.","spiritual_context":"The call to return is matched by the demand for enduring love rather than momentary religious display.","present_day_context":"Do not substitute occasional enthusiasm for sustained integrity. Design habits and accountability that make loyalty visible over time.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Joel 2:1","Joel 2:2","Joel 2:3","Joel 2:4","Joel 2:5","Joel 2:6","Joel 2:7","Joel 2:8","Joel 2:9","Joel 2:10","Joel 2:11","Joel 2:12","Joel 2:13","Joel 2:14","Joel 2:15","Joel 2:16","Joel 2:17","Joel 2:18","Joel 2:19","Joel 2:20","Joel 2:21","Joel 2:22","Joel 2:23","Joel 2:24","Joel 2:25","Joel 2:26","Joel 2:27","Joel 2:28","Joel 2:29","Joel 2:30","Joel 2:31","Joel 2:32"],"historical_context":"Joel uses locust imagery, day-of-the-Lord language and communal lament. Scholars debate aspects of the book''s dating and historical referents; its imagery should not be treated as a modern event calendar.","spiritual_context":"The passage moves from alarm toward repentance, renewal and the promise of the Spirit poured out widely.","present_day_context":"Respond to crisis with transparent assessment and shared responsibility. Let hope mobilize service rather than fuel sensational prediction.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash","https://theharbingerbook.com/the-harbinger/"]},{"refs":["Amos 5:1","Amos 5:2","Amos 5:3","Amos 5:4","Amos 5:5","Amos 5:6","Amos 5:7","Amos 5:8","Amos 5:9","Amos 5:10","Amos 5:11","Amos 5:12","Amos 5:13","Amos 5:14","Amos 5:15","Amos 5:16","Amos 5:17","Amos 5:18","Amos 5:19","Amos 5:20","Amos 5:21","Amos 5:22","Amos 5:23","Amos 5:24","Amos 5:25","Amos 5:26","Amos 5:27"],"historical_context":"Amos challenges prosperous northern Israel over distorted justice and religious complacency. The prophet''s critique is rooted in the inequalities of his society.","spiritual_context":"God''s demand for justice exposes worship that ignores exploitation. Moral courage includes criticizing practices that benefit powerful people.","present_day_context":"Examine how your policies affect workers and the poor. Public success cannot excuse private unfairness or institutional corruption.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Obadiah 1:1","Obadiah 1:2","Obadiah 1:3","Obadiah 1:4","Obadiah 1:5","Obadiah 1:6","Obadiah 1:7","Obadiah 1:8","Obadiah 1:9","Obadiah 1:10","Obadiah 1:11","Obadiah 1:12","Obadiah 1:13","Obadiah 1:14","Obadiah 1:15","Obadiah 1:16","Obadiah 1:17","Obadiah 1:18","Obadiah 1:19","Obadiah 1:20","Obadiah 1:21"],"historical_context":"Obadiah speaks against Edom in the setting of conflict surrounding Jerusalem''s downfall. The prophetic oracle criticizes pride and betrayal during a neighbor''s distress.","spiritual_context":"The passage warns against exploiting another community''s vulnerability and taking satisfaction in another''s ruin.","present_day_context":"When rivals suffer, reject opportunism and contempt. Durable influence is earned through principled conduct, including toward people outside your group.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Jonah 4:1","Jonah 4:2","Jonah 4:3","Jonah 4:4","Jonah 4:5","Jonah 4:6","Jonah 4:7","Jonah 4:8","Jonah 4:9","Jonah 4:10","Jonah 4:11"],"historical_context":"Jonah is a prophetic story set against Nineveh, a symbol of Assyrian power. The narrative uses dialogue and irony to challenge narrow expectations about mercy.","spiritual_context":"Jonah''s anger reveals how difficult compassion can be when it reaches people we think deserve judgment.","present_day_context":"Examine whether your cause has made you indifferent to people outside your circle. Hold firm convictions while remaining open to surprising mercy.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Nahum 1:1","Nahum 1:2","Nahum 1:3","Nahum 1:4","Nahum 1:5","Nahum 1:6","Nahum 1:7","Nahum 1:8","Nahum 1:9","Nahum 1:10","Nahum 1:11","Nahum 1:12","Nahum 1:13","Nahum 1:14","Nahum 1:15"],"historical_context":"Nahum announces judgment on Nineveh in the shadow of Assyrian power. Poetry conveys both the terror of empire and hope for those oppressed by it.","spiritual_context":"The passage gives language to communities damaged by violence while reminding readers not to turn ancient judgment oracles into personal threats.","present_day_context":"Support people facing unjust power without imitating the cruelty you oppose. Make room for justice, accountability and restraint.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash","https://www.asor.org/am/2023/approved-sessions-2023"]},{"refs":["Zephaniah 3:1","Zephaniah 3:2","Zephaniah 3:3","Zephaniah 3:4","Zephaniah 3:5","Zephaniah 3:6","Zephaniah 3:7","Zephaniah 3:8","Zephaniah 3:9","Zephaniah 3:10","Zephaniah 3:11","Zephaniah 3:12","Zephaniah 3:13","Zephaniah 3:14","Zephaniah 3:15","Zephaniah 3:16","Zephaniah 3:17","Zephaniah 3:18","Zephaniah 3:19","Zephaniah 3:20"],"historical_context":"Zephaniah moves from critique of injustice and corrupt leadership to a vision of restoration. Its prophetic language addresses both civic and spiritual breakdown.","spiritual_context":"Hope is connected with humility, truthful speech and a renewed community, not merely the removal of an opponent.","present_day_context":"Rebuild trust by dealing honestly, making room for the overlooked and establishing consistent standards for those in authority.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Haggai 1:1","Haggai 1:2","Haggai 1:3","Haggai 1:4","Haggai 1:5","Haggai 1:6","Haggai 1:7","Haggai 1:8","Haggai 1:9","Haggai 1:10","Haggai 1:11","Haggai 1:12","Haggai 1:13","Haggai 1:14","Haggai 1:15"],"historical_context":"Haggai addresses a postexilic community rebuilding in Persian-period Judah. Competing priorities between households and shared religious life frame the prophet''s challenge.","spiritual_context":"The call to consider one''s ways turns faith into a question of attention and action. Neglect of a common mission can look reasonable one choice at a time.","present_day_context":"Audit where your time and resources go. A mission usually fails through repeated small deferrals before it fails publicly.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"]},{"refs":["Zechariah 4:1","Zechariah 4:2","Zechariah 4:3","Zechariah 4:4","Zechariah 4:5","Zechariah 4:6","Zechariah 4:7","Zechariah 4:8","Zechariah 4:9","Zechariah 4:10","Zechariah 4:11","Zechariah 4:12","Zechariah 4:13","Zechariah 4:14"],"historical_context":"Zechariah''s symbolic visions belong to the rebuilding period after exile. The lampstand and olive-tree imagery require literary care rather than literal reconstruction.","spiritual_context":"The passage associates restoration with divine empowerment rather than human force alone. Patience with small beginnings is part of its message.","present_day_context":"Do not despise early-stage work. Build reliable foundations and assess progress before demanding a spectacular result.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.metmuseum.org/de/perspectives/cyrus-and-the-judean-diaspora","https://www.sefaria.org/topics/midrash"]},{"refs":["Malachi 3:1","Malachi 3:2","Malachi 3:3","Malachi 3:4","Malachi 3:5","Malachi 3:6","Malachi 3:7","Malachi 3:8","Malachi 3:9","Malachi 3:10","Malachi 3:11","Malachi 3:12","Malachi 3:13","Malachi 3:14","Malachi 3:15","Malachi 3:16","Malachi 3:17","Malachi 3:18"],"historical_context":"Malachi critiques religious practice, social faithlessness and the conduct of temple personnel in the postexilic community. Its speech is structured as disputes and responses.","spiritual_context":"The text connects covenant loyalty with justice and integrity, not only offerings. Its language of refinement presses toward truthful worship.","present_day_context":"Set transparent standards for money, relationships and responsibility. Do not use generous public gifts to conceal dishonest conduct.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Mark 10:35","Mark 10:36","Mark 10:37","Mark 10:38","Mark 10:39","Mark 10:40","Mark 10:41","Mark 10:42","Mark 10:43","Mark 10:44","Mark 10:45","Mark 10:46","Mark 10:47","Mark 10:48","Mark 10:49","Mark 10:50","Mark 10:51","Mark 10:52"],"historical_context":"Mark places disputes over status close to Jesus'' journey toward suffering and a story of healing near Jericho. The literary placement questions conventional greatness.","spiritual_context":"Jesus defines leadership by service rather than domination, then responds to a marginalized person''s request.","present_day_context":"Give people voice before deciding what help they need. Authority is strongest when it serves rather than demands deference.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx"]},{"refs":["2 Corinthians 4:1","2 Corinthians 4:2","2 Corinthians 4:3","2 Corinthians 4:4","2 Corinthians 4:5","2 Corinthians 4:6","2 Corinthians 4:7","2 Corinthians 4:8","2 Corinthians 4:9","2 Corinthians 4:10","2 Corinthians 4:11","2 Corinthians 4:12","2 Corinthians 4:13","2 Corinthians 4:14","2 Corinthians 4:15","2 Corinthians 4:16","2 Corinthians 4:17","2 Corinthians 4:18"],"historical_context":"Paul speaks of fragile human messengers carrying a valuable message amid pressures facing the early church. The imagery of clay jars emphasizes weakness and endurance.","spiritual_context":"The passage resists both despair and self-glorification. Ministry credibility rests on truth and perseverance rather than personal invincibility.","present_day_context":"Be transparent about limitations and remain accountable under pressure. The work can be meaningful without pretending its leaders are flawless.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["Galatians 5:1","Galatians 5:2","Galatians 5:3","Galatians 5:4","Galatians 5:5","Galatians 5:6","Galatians 5:7","Galatians 5:8","Galatians 5:9","Galatians 5:10","Galatians 5:11","Galatians 5:12","Galatians 5:13","Galatians 5:14","Galatians 5:15","Galatians 5:16","Galatians 5:17","Galatians 5:18","Galatians 5:19","Galatians 5:20","Galatians 5:21","Galatians 5:22","Galatians 5:23","Galatians 5:24","Galatians 5:25","Galatians 5:26"],"historical_context":"Galatians addresses disputes over identity, law and freedom in early Christian communities. Paul turns from contested belonging to the ethics of life by the Spirit.","spiritual_context":"Freedom is not license to consume others; it becomes love expressed through self-control, patience and service.","present_day_context":"Challenge systems that mistake control for maturity. Give people genuine responsibility while holding everyone to humane standards.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx","https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["Philippians 2:1","Philippians 2:2","Philippians 2:3","Philippians 2:4","Philippians 2:5","Philippians 2:6","Philippians 2:7","Philippians 2:8","Philippians 2:9","Philippians 2:10","Philippians 2:11","Philippians 2:12","Philippians 2:13","Philippians 2:14","Philippians 2:15","Philippians 2:16","Philippians 2:17","Philippians 2:18"],"historical_context":"Paul writes to a community within a Roman colonial setting where honor and rank were socially significant. The Christ hymn reframes status through humility.","spiritual_context":"The example of Christ turns self-giving into a model for common life. Cooperation is presented as more than surface politeness.","present_day_context":"Share credit, listen seriously and choose service when ambition tempts you to compete for visibility. Strong teams can disagree without contempt.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx"]},{"refs":["Colossians 3:1","Colossians 3:2","Colossians 3:3","Colossians 3:4","Colossians 3:5","Colossians 3:6","Colossians 3:7","Colossians 3:8","Colossians 3:9","Colossians 3:10","Colossians 3:11","Colossians 3:12","Colossians 3:13","Colossians 3:14","Colossians 3:15","Colossians 3:16","Colossians 3:17","Colossians 3:18","Colossians 3:19","Colossians 3:20","Colossians 3:21","Colossians 3:22","Colossians 3:23","Colossians 3:24","Colossians 3:25"],"historical_context":"Colossians addresses Christian identity through household and communal responsibilities. Ancient household instructions must be studied in their social context and not used to justify abuse.","spiritual_context":"Renewed life is described through compassion, forgiveness and truthful conduct, not a badge of superiority.","present_day_context":"Make respect and accountability concrete in the home and workplace. Reject excuses that use authority to silence or exploit others.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["1 Thessalonians 5:1","1 Thessalonians 5:2","1 Thessalonians 5:3","1 Thessalonians 5:4","1 Thessalonians 5:5","1 Thessalonians 5:6","1 Thessalonians 5:7","1 Thessalonians 5:8","1 Thessalonians 5:9","1 Thessalonians 5:10","1 Thessalonians 5:11","1 Thessalonians 5:12","1 Thessalonians 5:13","1 Thessalonians 5:14","1 Thessalonians 5:15","1 Thessalonians 5:16","1 Thessalonians 5:17","1 Thessalonians 5:18","1 Thessalonians 5:19","1 Thessalonians 5:20","1 Thessalonians 5:21","1 Thessalonians 5:22","1 Thessalonians 5:23","1 Thessalonians 5:24","1 Thessalonians 5:25","1 Thessalonians 5:26","1 Thessalonians 5:27","1 Thessalonians 5:28"],"historical_context":"The early Thessalonian community receives teaching on vigilance, encouragement and its shared life while expecting Christ''s return. Apocalyptic language shapes an ethic of readiness.","spiritual_context":"Watchfulness is paired with patient care, discernment and peace. It does not require constant alarm or speculation.","present_day_context":"Prepare responsibly for uncertainty while continuing useful work. Encourage those who struggle and test extraordinary claims carefully.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["2 Thessalonians 3:1","2 Thessalonians 3:2","2 Thessalonians 3:3","2 Thessalonians 3:4","2 Thessalonians 3:5","2 Thessalonians 3:6","2 Thessalonians 3:7","2 Thessalonians 3:8","2 Thessalonians 3:9","2 Thessalonians 3:10","2 Thessalonians 3:11","2 Thessalonians 3:12","2 Thessalonians 3:13","2 Thessalonians 3:14","2 Thessalonians 3:15","2 Thessalonians 3:16","2 Thessalonians 3:17","2 Thessalonians 3:18"],"historical_context":"The letter addresses community discipline, work and disruptive behavior amid questions about the Lord''s coming. Its historical authorship and occasion are discussed in scholarship.","spiritual_context":"Hope does not release a community from ordinary responsibilities. Persistence and productive service matter.","present_day_context":"Build systems that support people in need and also establish fair expectations for participation. Avoid using spiritual anticipation as an excuse for neglect.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["1 Timothy 4:1","1 Timothy 4:2","1 Timothy 4:3","1 Timothy 4:4","1 Timothy 4:5","1 Timothy 4:6","1 Timothy 4:7","1 Timothy 4:8","1 Timothy 4:9","1 Timothy 4:10","1 Timothy 4:11","1 Timothy 4:12","1 Timothy 4:13","1 Timothy 4:14","1 Timothy 4:15","1 Timothy 4:16"],"historical_context":"The pastoral instruction concerns teaching, communal example and care in a developing church setting. Dating and authorship are debated among scholars.","spiritual_context":"Credible leadership requires attentiveness to speech, life, love, faith and character, not a title alone.","present_day_context":"Keep learning, receive correction and model what you teach. Consistency over time is a stronger qualification than personal branding.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx"]},{"refs":["2 Timothy 1:1","2 Timothy 1:2","2 Timothy 1:3","2 Timothy 1:4","2 Timothy 1:5","2 Timothy 1:6","2 Timothy 1:7","2 Timothy 1:8","2 Timothy 1:9","2 Timothy 1:10","2 Timothy 1:11","2 Timothy 1:12","2 Timothy 1:13","2 Timothy 1:14","2 Timothy 1:15","2 Timothy 1:16","2 Timothy 1:17","2 Timothy 1:18"],"historical_context":"This pastoral letter uses the language of mentorship, remembered faith and endurance. Its historical setting is traditionally associated with Paul''s later ministry, while critical scholarship debates authorship.","spiritual_context":"Courage is connected with a disciplined spirit and loyalty to an entrusted message. Mentorship prepares the next person to carry the work.","present_day_context":"Equip successors with both conviction and practical skill. Pass on a mission in a form that others can responsibly continue.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx","https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["Titus 2:1","Titus 2:2","Titus 2:3","Titus 2:4","Titus 2:5","Titus 2:6","Titus 2:7","Titus 2:8","Titus 2:9","Titus 2:10","Titus 2:11","Titus 2:12","Titus 2:13","Titus 2:14","Titus 2:15"],"historical_context":"The letter links teaching to conduct among different households and age groups in the ancient Mediterranean world. Its social categories require historical interpretation.","spiritual_context":"Grace trains people in self-control, integrity and care. Public credibility grows out of daily character.","present_day_context":"Create mentoring relationships across generations. Establish expectations through example instead of lectures alone.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx"]},{"refs":["Philemon 1:1","Philemon 1:2","Philemon 1:3","Philemon 1:4","Philemon 1:5","Philemon 1:6","Philemon 1:7","Philemon 1:8","Philemon 1:9","Philemon 1:10","Philemon 1:11","Philemon 1:12","Philemon 1:13","Philemon 1:14","Philemon 1:15","Philemon 1:16","Philemon 1:17","Philemon 1:18","Philemon 1:19","Philemon 1:20","Philemon 1:21","Philemon 1:22","Philemon 1:23","Philemon 1:24","Philemon 1:25"],"historical_context":"Philemon is a short personal letter concerning Onesimus within the setting of ancient Roman slavery. Its language seeks reconciliation, but the institution of slavery remains morally grave.","spiritual_context":"Paul presses a relationship toward recognition of a brother rather than mere property or status. The text invites serious ethical examination, not romanticizing slavery.","present_day_context":"When power imbalances distort relationships, use influence to restore dignity and freedom. Private justice is part of public faithfulness.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash"]},{"refs":["Hebrews 11:1","Hebrews 11:2","Hebrews 11:3","Hebrews 11:4","Hebrews 11:5","Hebrews 11:6","Hebrews 11:7","Hebrews 11:8","Hebrews 11:9","Hebrews 11:10","Hebrews 11:11","Hebrews 11:12","Hebrews 11:13","Hebrews 11:14","Hebrews 11:15","Hebrews 11:16","Hebrews 11:17","Hebrews 11:18","Hebrews 11:19","Hebrews 11:20","Hebrews 11:21","Hebrews 11:22","Hebrews 11:23","Hebrews 11:24","Hebrews 11:25","Hebrews 11:26","Hebrews 11:27","Hebrews 11:28","Hebrews 11:29","Hebrews 11:30","Hebrews 11:31","Hebrews 11:32","Hebrews 11:33","Hebrews 11:34","Hebrews 11:35","Hebrews 11:36","Hebrews 11:37","Hebrews 11:38","Hebrews 11:39","Hebrews 11:40"],"historical_context":"Hebrews retells figures from Israel''s Scriptures as examples of trust through uncertainty. Its catalogue is theological memory, not independent historical proof of each event.","spiritual_context":"Faith is portrayed through persistence without full possession of promised outcomes. Courage can mean enduring without applause.","present_day_context":"Work faithfully on goals whose results may take longer than your tenure. Build what others can carry forward.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash","https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["1 Peter 4:1","1 Peter 4:2","1 Peter 4:3","1 Peter 4:4","1 Peter 4:5","1 Peter 4:6","1 Peter 4:7","1 Peter 4:8","1 Peter 4:9","1 Peter 4:10","1 Peter 4:11","1 Peter 4:12","1 Peter 4:13","1 Peter 4:14","1 Peter 4:15","1 Peter 4:16","1 Peter 4:17","1 Peter 4:18","1 Peter 4:19"],"historical_context":"The letter addresses Christian communities coping with social pressure and suffering under the Roman world. Scholars debate precise settings and dating.","spiritual_context":"Service, hospitality and steadfastness are presented as responses to hardship. Suffering itself is not proof that a decision was wise.","present_day_context":"Support people under pressure and resist retaliatory cruelty. Let courage include prudence, mutual care and honest self-examination.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["2 Peter 1:1","2 Peter 1:2","2 Peter 1:3","2 Peter 1:4","2 Peter 1:5","2 Peter 1:6","2 Peter 1:7","2 Peter 1:8","2 Peter 1:9","2 Peter 1:10","2 Peter 1:11","2 Peter 1:12","2 Peter 1:13","2 Peter 1:14","2 Peter 1:15","2 Peter 1:16","2 Peter 1:17","2 Peter 1:18","2 Peter 1:19","2 Peter 1:20","2 Peter 1:21"],"historical_context":"The letter urges moral growth, reliable memory and careful attention to prophetic witness. Its authorship and date are debated in modern scholarship.","spiritual_context":"Growth is depicted as a chain of virtues rather than a single dramatic moment. Discernment tests claims against trustworthy testimony.","present_day_context":"Develop knowledge, patience and self-control alongside conviction. A strong vision needs evidence and character to support it.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["1 John 4:1","1 John 4:2","1 John 4:3","1 John 4:4","1 John 4:5","1 John 4:6","1 John 4:7","1 John 4:8","1 John 4:9","1 John 4:10","1 John 4:11","1 John 4:12","1 John 4:13","1 John 4:14","1 John 4:15","1 John 4:16","1 John 4:17","1 John 4:18","1 John 4:19","1 John 4:20","1 John 4:21"],"historical_context":"The letter tests claims about spirits and love within a community dealing with division. It treats confession and conduct as inseparable.","spiritual_context":"Spiritual discernment is not fascination with novelty; love and truth matter together. Fear does not need to govern relationships.","present_day_context":"Assess leaders and movements by their treatment of people, not only by powerful language. Correct error without losing compassion.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["2 John 1:1","2 John 1:2","2 John 1:3","2 John 1:4","2 John 1:5","2 John 1:6","2 John 1:7","2 John 1:8","2 John 1:9","2 John 1:10","2 John 1:11","2 John 1:12","2 John 1:13"],"historical_context":"This brief letter addresses truth, love and hospitality amid concerns about deceptive teaching. The social setting involves traveling teachers and house-based communities.","spiritual_context":"The call to love is paired with discernment. Boundaries protect the community without removing the responsibility to act with integrity.","present_day_context":"Build clear criteria for people entrusted with influence. Hospitality and accountability work best together.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["3 John 1:1","3 John 1:2","3 John 1:3","3 John 1:4","3 John 1:5","3 John 1:6","3 John 1:7","3 John 1:8","3 John 1:9","3 John 1:10","3 John 1:11","3 John 1:12","3 John 1:13","3 John 1:14"],"historical_context":"The letter discusses hospitality, itinerant workers and a leader who refuses to welcome others. It reveals that early Christian communities also struggled with personal rivalry.","spiritual_context":"The contrast between generosity and controlling behavior makes everyday leadership choices spiritually consequential.","present_day_context":"Do not let gatekeeping become a substitute for stewardship. Welcome trustworthy collaborators and confront misuse of influence constructively.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]},{"refs":["Jude 1:1","Jude 1:2","Jude 1:3","Jude 1:4","Jude 1:5","Jude 1:6","Jude 1:7","Jude 1:8","Jude 1:9","Jude 1:10","Jude 1:11","Jude 1:12","Jude 1:13","Jude 1:14","Jude 1:15","Jude 1:16","Jude 1:17","Jude 1:18","Jude 1:19","Jude 1:20","Jude 1:21","Jude 1:22","Jude 1:23","Jude 1:24","Jude 1:25"],"historical_context":"Jude warns against corrupt behavior through references to Jewish scriptural and traditional material. Its allusions should be traced carefully rather than treated as straightforward independent chronicles.","spiritual_context":"The letter couples firm discernment with mercy toward people who are wavering. Integrity matters more than sensational claims.","present_day_context":"Address destructive behavior without abandoning patient care for those caught in confusion. Courage and compassion need not compete.","research_note":"Original Instructor passage guide: historical background is distinct from later tradition, theological interpretation and present-day analogy. Disputed datings or authorship are marked as debated.","source_links":["https://www.sefaria.org/topics/midrash","https://publications.morningstarministries.org/strategic-prophetic-words?lang=en"]}]'::jsonb)
as grp(refs jsonb,historical_context text,spiritual_context text,present_day_context text,research_note text,source_links jsonb)
cross join lateral jsonb_array_elements_text(grp.refs) verse(value)
on conflict(reference) do update set historical_context=excluded.historical_context,spiritual_context=excluded.spiritual_context,
 present_day_context=excluded.present_day_context,research_note=excluded.research_note,source_links=excluded.source_links,updated_at=now();


-- When a future FCX event becomes available, convert the oldest earned
-- Scripture ticket vouchers into genuine registrations, respecting capacity.
create or replace function public.assign_quarterly_scripture_fcx_tickets()
returns trigger language plpgsql security definer set search_path=''
as $fn$
declare
 v_award public.quarterly_verse_fcx_awards%rowtype;
 v_count integer;
begin
 if not new.is_active or new.event_date < (now() at time zone 'Africa/Douala')::date
 then return new; end if;
 for v_award in
   select * from public.quarterly_verse_fcx_awards
   where status='awaiting_event'
   order by created_at,quest_id for update skip locked
 loop
   select count(*) into v_count from public.fcx_registrations where event_id=new.id;
   if v_count>=new.capacity then exit; end if;
   if exists (select 1 from public.fcx_registrations
              where event_id=new.id and user_id=v_award.user_id)
   then continue; end if;
   insert into public.fcx_registrations(event_id,user_id,payment_source,added_by)
     values(new.id,v_award.user_id,'app',v_award.user_id);
   update public.quarterly_verse_fcx_awards
     set event_id=new.id,status='registered'
     where quest_id=v_award.quest_id and status='awaiting_event';
   perform public.notify_user(v_award.user_id,null,'fcx',
     'Your free FCX ticket is ready',
     'Your Scripture discovery prize has been registered for the upcoming Full Circle Experience.',
     'fcx',jsonb_build_object('event_id',new.id,'quest_id',v_award.quest_id));
 end loop;
 return new;
end $fn$;
revoke all on function public.assign_quarterly_scripture_fcx_tickets() from public,anon,authenticated;
drop trigger if exists apply_scripture_fcx_vouchers_on_event on public.fcx_events;
create trigger apply_scripture_fcx_vouchers_on_event
after insert or update of is_active,event_date,capacity on public.fcx_events
for each row execute function public.assign_quarterly_scripture_fcx_tickets();

-- Use relevant original Josephus volumes and Munroe's archived official teaching platform.

update public.instructor_verse_contexts t set source_links=(
 select jsonb_agg(
  case
   when value='https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx' then 'https://www.munroeglobalmedia.com/about-us'
   when value='https://adfonteslibrary.org/work-st-josephus-antiquities-1' and reference like 'Exodus %' then 'https://penelope.uchicago.edu/josephus/ant-2.html'
   when value='https://adfonteslibrary.org/work-st-josephus-antiquities-1' and reference like 'Ruth %' then 'https://penelope.uchicago.edu/josephus/ant-5.html'
   when value='https://adfonteslibrary.org/work-st-josephus-antiquities-1' and reference like '1 Samuel %' then 'https://penelope.uchicago.edu/josephus/ant-6.html'
   when value='https://adfonteslibrary.org/work-st-josephus-antiquities-1' and reference like '2 Samuel %' then 'https://penelope.uchicago.edu/josephus/ant-7.html'
   when value='https://adfonteslibrary.org/work-st-josephus-antiquities-1' then 'https://penelope.uchicago.edu/josephus/ant-1.html'
   else value end
 ) from jsonb_array_elements_text(t.source_links) as src(value)
) where source_links::text like '%https://secure.cbn.com/700club/guests/bios/myles_munroe_043012.aspx%' or source_links::text like '%https://adfonteslibrary.org/work-st-josephus-antiquities-1%';
update public.instructor_verse_contexts
set source_links=source_links||'["https://penelope.uchicago.edu/josephus/ant-5.html"]'::jsonb
where reference like 'Judges %'
 and source_links::text not like '%penelope.uchicago.edu%';

-- Protect the audited first-finder Denarii award from ordinary subscription restrictions.
CREATE OR REPLACE FUNCTION public.enforce_owned_subscription_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  owner_id uuid := nullif(coalesce(to_jsonb(NEW)->>'user_id',to_jsonb(NEW)->>'sender_id'),'')::uuid;
BEGIN
  IF auth.uid() IS NULL OR auth.role()='service_role' OR owner_id IS DISTINCT FROM auth.uid()
     OR public.has_current_subscription_access(owner_id) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='quiz_attempts' AND EXISTS (
    SELECT 1 FROM public.quiz_sessions WHERE id=(to_jsonb(NEW)->>'quiz_session_id')::uuid AND quiz_type='saturday'
  ) THEN RETURN NEW; END IF;
  -- Reward is free to every first-finder, even without a subscription.
  -- Validate an actual won discovery, not just a client-supplied source label.
  IF TG_TABLE_NAME='denarii_ledger_entries'
     AND to_jsonb(NEW)->>'source_type'='verse_quest'
     AND EXISTS (
       SELECT 1 FROM public.quarterly_verse_quests quest
       WHERE quest.id::text=to_jsonb(NEW)->>'source_reference'
         AND quest.winner_user_id=owner_id
         AND quest.prize_type='denarii'
         AND quest.claimed_at IS NOT NULL
         AND quest.prize_quantity=(to_jsonb(NEW)->>'amount')::integer
     ) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='denarii_ledger_entries' AND (
    to_jsonb(NEW)->>'source_type' IN ('game_level','game_blitz')
    OR (to_jsonb(NEW)->>'source_type'='quiz_reward' AND EXISTS (
      SELECT 1 FROM public.quiz_attempts a JOIN public.quiz_sessions s ON s.id=a.quiz_session_id
      WHERE a.id::text=to_jsonb(NEW)->>'source_reference' AND a.user_id=owner_id AND s.quiz_type='saturday'
    ))
  ) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'SUBSCRIPTION_REQUIRED: Your subscription or free trial has expired.';
END;
$function$
;
CREATE UNIQUE INDEX IF NOT EXISTS verse_quest_unique_wallet_award ON public.denarii_ledger_entries(source_reference) WHERE source_type='verse_quest';
